<style>
.gb-wrap { max-width:1100px; margin:0 auto; padding:24px 16px 80px; display:grid; grid-template-columns:1fr 320px; gap:24px; align-items:flex-start; }
@media (max-width:1024px) {
  .gb-wrap { grid-template-columns:1fr; padding:12px 10px 120px; gap:14px; }
  /* Keep the complete price, duration, voucher and tip controls available on phones. */
  .gb-sidebar-full { display:flex !important; position:static !important; gap:14px !important; }
  /* The full sidebar is visible on mobile, so do not duplicate its checkout button. */
  .gb-sticky-bar { display:none !important; }
}
@media (min-width:1025px) { .gb-sidebar-full { display:block; } .gb-sticky-bar { display:none !important; } }
.gb-sticky-bar { display:none; position:fixed; bottom:0; left:0; right:0; background:#fff; border-top:1px solid #f1e4ec; padding:10px 16px; z-index:900; align-items:center; gap:12px; box-shadow:0 -4px 20px rgba(232,88,154,.08); }
.gb-sticky-total { flex:1; min-width:0; } .gb-sticky-total .label { font-size:11px; color:#7a7090; font-weight:600; } .gb-sticky-total .amount { font-size:22px; font-weight:800; color:#e8589a; }
.gb-sticky-submit { background:linear-gradient(135deg,#e8589a,#e8589a); color:white; border:none; border-radius:50px; padding:13px 22px; font-size:14px; font-weight:800; cursor:pointer; white-space:nowrap; }
.gb-sticky-submit:active { transform:scale(.97); }
.icon-nav { display:flex; gap:8px; overflow-x:auto; padding-bottom:4px; -webkit-overflow-scrolling:touch; scrollbar-width:none; } .icon-nav::-webkit-scrollbar { display:none; }
.val-tabs .icon-tab { min-width:105px; }
.val-card-head { display:flex; align-items:center; justify-content:space-between; gap:12px; padding-bottom:12px; margin-bottom:16px; border-bottom:1px solid #f7d8e5; }
.val-card-title { font-size:15px; font-weight:800; color:#2b1b24; }
.val-field-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }
.val-choice-row { display:flex; flex-wrap:wrap; gap:10px; }
.val-choice { position:relative; cursor:pointer; }
.val-choice input { position:absolute; opacity:0; pointer-events:none; }
.val-choice span { display:block; padding:11px 16px; border:1.5px solid #f2cedd; border-radius:13px; background:#fff; color:#3c2932; font-weight:700; font-size:13px; }
.val-choice input:checked + span { border-color:#ff4f91; background:#fff1f6; color:#e91e70; box-shadow:0 0 0 2px rgba(255,79,145,.08); }
.val-upload { min-height:92px; display:flex; align-items:center; justify-content:center; flex-direction:column; gap:6px; border:1.5px dashed #ff9fbd; border-radius:14px; background:#fffaf3; color:#e91e70; font-weight:700; cursor:pointer; overflow:hidden; }
.val-upload img { width:100%; height:92px; object-fit:cover; display:none; }
.val-message-row { display:grid; grid-template-columns:28px 1fr 38px; gap:8px; align-items:start; margin-bottom:9px; }
.val-message-no { height:30px; display:grid; place-items:center; border-radius:8px; background:#ffe3ed; color:#c83269; font-weight:800; font-size:12px; }
.val-remove { height:40px; border:0; border-radius:11px; background:#ffe1e5; color:#ef6680; font-size:18px; cursor:pointer; }
