<!-- MODAL: QUÀ CHƯA ĐẦY ĐỦ -->
<div class="gb-modal-bg" id="modal-incomplete">
    <div class="gb-modal">
        <h2 style="font-size:18px; font-weight:800; color:#3d3551; margin-bottom:6px;">Quà chưa đầy đủ</h2>
        <p style="font-size:13px; color:#7a7090; margin-bottom:14px;">Bạn chưa thêm ảnh cho quả cầu 3D</p>
        <div style="border:2px dashed #f0c0cc; border-radius:14px; padding:12px; margin-bottom:16px; display:flex; align-items:center; gap:12px; text-align:left;">
            <img src="templates/mon-qua-nho-2010/cover.webp?v=1794025288" onerror="this.onerror=null; this.src='assets/images/og-image.jpg';" loading="lazy" alt="Template" style="width:72px; height:72px; border-radius:10px; object-fit:cover; flex-shrink:0; border:2px solid #fce7f3;">
            <div>
                <div style="font-size:13px; font-weight:700; color:#3d3551;">Món Quà Nhỏ 3D · 19/11 &amp; Mọi Dịp Đặc Biệt 🎁</div>
                <div style="font-size:12px; color:#a79fb8; margin-top:4px;">Thêm ảnh quả cầu 3D sẽ giúp món quà sinh động hơn.</div>
            </div>
        </div>
        <div class="gb-incomplete-actions">
            <button type="button" class="gb-inc-btn gb-inc-btn--back" onclick="closeModal('modal-incomplete')"><span>← Quay lại thêm</span></button>
            <button type="button" class="gb-inc-btn gb-inc-btn--pay" onclick="proceedToPayment()"><span class="gb-inc-ico" aria-hidden="true">💳</span><span>Vẫn tiếp tục thanh toán</span><span class="gb-inc-arrow" aria-hidden="true">→</span></button>
        </div>
        <style>
        .gb-incomplete-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
        .gb-inc-btn {
            display: inline-flex; align-items: center; justify-content: center; gap: 8px;
            min-height: 48px; padding: 10px 16px; border-radius: 999px;
            font-size: 14px; font-weight: 800; cursor: pointer; line-height: 1.2;
            transition: transform .15s ease, box-shadow .15s ease, background .15s ease;
        }
        .gb-inc-btn:active { transform: scale(.98); }
        .gb-inc-btn--back {
            color: #d6377f; background: #fff; border: 2px solid #f7c3da;
        }
        .gb-inc-btn--back:hover { background: #fff3f8; border-color: #e8589a; }
        .gb-inc-btn--pay {
            color: #fff; border: 0;
            background: linear-gradient(135deg, #ff7eb3 0%, #e8589a 45%, #9b5cf6 100%);
            box-shadow: 0 10px 22px rgba(232, 88, 154, .32);
        }
        .gb-inc-btn--pay:hover { transform: translateY(-1px); box-shadow: 0 14px 28px rgba(232, 88, 154, .4); }
        .gb-inc-ico { font-size: 16px; }
        .gb-inc-arrow { font-size: 16px; transition: transform .15s ease; }
        .gb-inc-btn--pay:hover .gb-inc-arrow { transform: translateX(3px); }
        .gb-inc-btn--pay { white-space: nowrap; }
