<script>
// ─── Tab/Section switching ───────────────────────────────────────
function switchSection(id, el) {
    document.querySelectorAll('.gb-section').forEach(s => s.classList.remove('active'));
    document.querySelectorAll('.icon-tab').forEach(t => t.classList.remove('active'));
    document.getElementById(id).classList.add('active');
    el.classList.add('active');
    if (id === 'sec-password') {
        setTimeout(initAllQrPreviews, 50);
    }
}

function renumberValentineMessages() {
    document.querySelectorAll('#val-chat-message-list .val-message-row').forEach(function(row, index) {
        var no = row.querySelector('.val-message-no');
        if (no) no.textContent = index + 1;
    });
}
function addValentineMessage() {
    var list = document.getElementById('val-chat-message-list');
    if (!list || list.children.length >= 12) return showToast('Tối đa 12 tin nhắn.', 'error');
    var row = document.createElement('div');
    row.className = 'val-message-row';
    row.innerHTML = '<span class="val-message-no"></span><textarea class="form-input" name="val_chat_messages[]" rows="2" placeholder="Nhập tin nhắn..."></textarea><button class="val-remove" type="button">×</button>';
    row.querySelector('textarea').addEventListener('input', sendLivePreviewUpdate);
    row.querySelector('button').addEventListener('click', function(){ removeValentineMessage(this); });
    list.appendChild(row); renumberValentineMessages(); row.querySelector('textarea').focus(); sendLivePreviewUpdate();
}
function removeValentineMessage(button) {
    var list = document.getElementById('val-chat-message-list');
    if (!list || list.children.length <= 1) return showToast('Cần giữ ít nhất 1 tin nhắn.', 'error');
    button.closest('.val-message-row').remove(); renumberValentineMessages(); sendLivePreviewUpdate();
}
function previewValentineSingle(input, previewId) {
    clearLivePreviewObjectUrls();
    var preview = document.getElementById(previewId);
    if (!preview || !input.files || !input.files[0]) return;
    preview.src = livePreviewObjectUrl(input.files[0]); preview.style.display = 'block';
    var labelText = preview.parentElement.querySelector('span'); if (labelText) labelText.style.display = 'none';
    sendLivePreviewUpdate();
}
function toggleValentineHeartMode() {
    var mode = document.querySelector('input[name="val_heart_mode"]:checked')?.value || 'days';
    var dateWrap = document.getElementById('val-love-date-wrap');
    var textWrap = document.getElementById('val-heart-text-wrap');
    if (dateWrap) dateWrap.style.display = mode === 'days' ? 'block' : 'none';
    if (textWrap) textWrap.style.display = mode === 'text' ? 'block' : 'none';
}
function useValentineLetterSample() {
    var field = document.getElementById('val_letter_content');
    if (!field) return;
    field.value = "Happy Valentine’s Day ngoan xinh yêu.\nThật sự may mắn vì đã gặp được em và được em yêu. Cảm ơn em luôn quan tâm, chăm sóc và yêu thương anh.\nAnh mong rằng mình vẫn mãi bên nhau, yêu thương và chia sẻ với nhau nhiều hơn.";
    updateValentineStatus(); sendLivePreviewUpdate();
}
function updateValentineStatus() {
    var chat = document.getElementById('recipient_name')?.value.trim();
    var letter = document.getElementById('val_letter_content')?.value.trim();
    var chatStatus = document.getElementById('st-val-chat');
    var letterStatus = document.getElementById('st-val-letter');
    if (chatStatus) { chatStatus.textContent = chat ? 'Đã điền' : 'Chưa điền'; chatStatus.style.color = chat ? '#22c55e' : '#a79fb8'; }
    if (letterStatus) { letterStatus.textContent = letter ? 'Đã điền' : 'Chưa điền'; letterStatus.style.color = letter ? '#22c55e' : '#a79fb8'; }
}
function updateValentinePasswordStatus() {
    var field = document.getElementById('password_value');
    var status = document.getElementById('st-sec-password');
    if (field && status) { status.textContent = field.value.length === 4 ? field.value : 'Cần 4 số'; status.style.color = field.value.length === 4 ? '#22c55e' : '#e8589a'; }
}

// ─── Particle toggle status ──────────────────────────────────────
function updateParticleStatus() {
    var on = document.getElementById('particleToggle')?.checked;
    var el = document.getElementById('st-sec-particle');
    if (el) {
        el.textContent = on ? 'Đã bật' : 'Đã tắt';
        el.style.color = on ? '#22c55e' : '#e8589a';
    }
}

// ─── Letter text status ───────────────────────────────────────────
function updateLetterStatus() {
    var v = document.getElementById('recipient_name')?.value?.trim();
    var el = document.getElementById('st-sec-letter');
    if (el) {
        el.textContent = v ? 'Đã điền' : 'Chưa điền';
        el.style.color = v ? '#22c55e' : '#a79fb8';
    }
}

// ─── Password section ─────────────────────────────────────────────
function togglePasswordSection() {
    var checked = document.getElementById('pass_toggle')?.checked;
    var container = document.getElementById('password_input_container');
    if (container) container.style.display = checked ? 'block' : 'none';
    var el = document.getElementById('st-sec-password');
    if(el) {
        var valPin = document.getElementById('password_value');
        el.textContent = !checked ? 'Đã tắt' : (valPin ? (valPin.value || 'Cần 4 số') : 'Đã bật');
        el.style.color = checked ? '#22c55e' : '#a79fb8';
    }
    var pr = document.getElementById('pr-password');
    if (pr) {
        pr.textContent = checked ? 'Miễn phí' : '—';
        pr.style.color = checked ? '#22c55e' : '#ccc';
        pr.className = 'price-val free';
    }
    updateTotal();
}

function toggleQRSection() {
    var checked = document.getElementById('enable_qr')?.checked;
    var container = document.getElementById('qr_settings_container');
    if (container) container.style.display = checked ? 'block' : 'none';
    
    var pr = document.getElementById('pr-qr');
    if (pr) {
        pr.textContent = checked ? '10.000đ' : '—';
        pr.style.color = checked ? '#e8589a' : '#ccc';
        pr.className = checked ? 'price-val' : 'price-val free';
    }
    updateTotal();
    if (checked) {
        setTimeout(initAllQrPreviews, 50);
    }
}

function selectQrTemplate(card) {
    document.querySelectorAll('.qr-template-card').forEach(function(c) { c.classList.remove('selected'); });
    card.classList.add('selected');
    var tid = card.getAttribute('data-id');
    var inp = document.getElementById('qr_template');
    if (inp) inp.value = tid;
}

var qrPreviewTargetUrl = "index.htmlg/DEMO2026";

// Phép xoay canvas tạo ra các điểm ảnh bán trong suốt ở cạnh module. Khi ảnh
// bị thu nhỏ, chúng nhìn thành nhiều sắc độ dù chỉ dùng một màu. Chuẩn hóa lại
// alpha và RGB sau khi vẽ để mọi điểm QR luôn có cùng một màu đặc.
function flattenQrCanvasInk(ctx, width, height, color) {
    var match = /^#([0-9a-f]{6})$/i.exec(color);
    if (!match) return;
    var value = parseInt(match[1], 16);
    var red = (value >> 16) & 255;
    var green = (value >> 8) & 255;
    var blue = value & 255;
    var image = ctx.getImageData(0, 0, width, height);
    var pixels = image.data;
    for (var i = 0; i < pixels.length; i += 4) {
        if (pixels[i + 3] >= 96) {
            pixels[i] = red;
            pixels[i + 1] = green;
            pixels[i + 2] = blue;
            pixels[i + 3] = 255;
        } else {
            pixels[i] = 0;
            pixels[i + 1] = 0;
            pixels[i + 2] = 0;
            pixels[i + 3] = 0;
        }
    }
    ctx.putImageData(image, 0, 0);
}

function fitMidAutumnQrCanvas(canvas, attempt) {
    var frame = canvas && canvas.closest ? canvas.closest('.qr-midautumn-preview') : null;
    if (!frame) return;
    attempt = attempt || 0;
    frame.style.setProperty('position', 'relative', 'important');
    var frameWidth = frame.clientWidth;
    if (frameWidth < 40 && attempt < 12) {
        setTimeout(function() { fitMidAutumnQrCanvas(canvas, attempt + 1); }, 60);
        return;
    }
    // Vị trí và cỡ mã do biến --qr-l/--qr-t/--qr-s của từng khung quyết định (CSS).
}

function drawMiniHeartQR(canvasId, color, heartShape, isFlower, backgroundColor) {
    try {
        if (typeof qrcode === 'undefined') return;
        var qr = qrcode(0, 'H');
        qr.addData(qrPreviewTargetUrl);
        qr.make();

        var N = qr.getModuleCount();
        var canvas = document.getElementById(canvasId);
        if (!canvas) return;
        var ctx = canvas.getContext('2d', { willReadFrequently: true });

        if (heartShape) {
            var heartCellSize = 5;
            var squareSize = N * heartCellSize;
            var heartSize = Math.ceil(2.28 * squareSize);
            canvas.width = heartSize;
            canvas.height = heartSize;
            ctx.clearRect(0, 0, heartSize, heartSize);
            ctx.imageSmoothingEnabled = false;

            var centerX = heartSize / 2;
            var centerY = (heartSize / 2) + (0.09 * squareSize);

            function wrapQrDataIndex(value) {
                var span = Math.max(1, N - 16);
                var wrapped = ((Math.round(value) - 8) % span + span) % span;
                return 8 + wrapped;
            }

            function isHeartFill(col, row) {
                if (col >= 0 && col < N && row >= 0 && row < N) {
                    if ((col <= 7 && row <= 7) || (col >= N - 8 && row <= 7) || (col <= 7 && row >= N - 8)) {
                        return false;
                    }
                    return qr.isDark(row, col);
                }

                var inRightLobe = col >= N &&
                    Math.pow(col - N, 2) + Math.pow(row - N / 2, 2) <= Math.pow(N / 2, 2);
                var inBottomLobe = row >= N &&
                    Math.pow(col - N / 2, 2) + Math.pow(row - N, 2) <= Math.pow(N / 2, 2);

                if (inRightLobe) {
                    return qr.isDark(
                        wrapQrDataIndex(row),
                        wrapQrDataIndex(2 * N - 9 - col)
                    );
                }
                if (inBottomLobe) {
                    return qr.isDark(
                        wrapQrDataIndex(2 * N - 9 - row),
                        wrapQrDataIndex(col)
                    );
                }
                return false;
            }

            ctx.save();
            ctx.translate(centerX, centerY);
            ctx.rotate(-135 * Math.PI / 180);

            if (isFlower) {
                var pad = 1.45 * heartCellSize;
                var r_rad = (N / 2) * heartCellSize + pad;

                ctx.save();
                ctx.shadowColor = 'rgba(70, 15, 30, 0.25)';
                ctx.shadowBlur = 10;
                ctx.shadowOffsetY = 3;
                ctx.beginPath();
                ctx.moveTo(-N/2 * heartCellSize - pad, -N/2 * heartCellSize - pad);
                ctx.lineTo(N/2 * heartCellSize + pad, -N/2 * heartCellSize - pad);
                ctx.arc(N/2 * heartCellSize, 0, r_rad, -Math.PI / 2, Math.PI / 2);
                ctx.arc(0, N/2 * heartCellSize, r_rad, 0, Math.PI);
                ctx.closePath();
                ctx.fillStyle = '#ffffff';
                ctx.fill();
                ctx.restore();

                ctx.beginPath();
                ctx.moveTo(-N/2 * heartCellSize - pad, -N/2 * heartCellSize - pad);
                ctx.lineTo(N/2 * heartCellSize + pad, -N/2 * heartCellSize - pad);
                ctx.arc(N/2 * heartCellSize, 0, r_rad, -Math.PI / 2, Math.PI / 2);
                ctx.arc(0, N/2 * heartCellSize, r_rad, 0, Math.PI);
                ctx.closePath();
                ctx.fillStyle = '#ffffff';
                ctx.fill();
            }

            ctx.fillStyle = color;

            for (var heartRow = 0; heartRow <= N * 1.5; heartRow++) {
                for (var heartCol = 0; heartCol <= N * 1.5; heartCol++) {
                    if (isHeartFill(heartCol, heartRow)) {
                        ctx.fillRect(
                            (heartCol - N / 2) * heartCellSize,
                            (heartRow - N / 2) * heartCellSize,
                            heartCellSize,
                            heartCellSize
                        );
                    }
                }
            }

            function drawHeartFinder(col, row) {
                var x = (col - N / 2) * heartCellSize;
                var y = (row - N / 2) * heartCellSize;
                var outer = 7 * heartCellSize;
                var inner = 3 * heartCellSize;
                if (isFlower) {
                    ctx.fillStyle = '#ffffff';
                    ctx.fillRect(x - heartCellSize, y - heartCellSize, outer + 2 * heartCellSize, outer + 2 * heartCellSize);
                } else {
                    ctx.clearRect(x - heartCellSize, y - heartCellSize, outer + 2 * heartCellSize, outer + 2 * heartCellSize);
                }
                ctx.fillStyle = color;
                ctx.fillRect(x, y, outer, outer);
                if (isFlower) {
                    ctx.fillStyle = '#ffffff';
                    ctx.fillRect(x + heartCellSize, y + heartCellSize, outer - 2 * heartCellSize, outer - 2 * heartCellSize);
                } else {
                    ctx.clearRect(x + heartCellSize, y + heartCellSize, outer - 2 * heartCellSize, outer - 2 * heartCellSize);
                }
                ctx.fillStyle = color;
                ctx.fillRect(x + 2 * heartCellSize, y + 2 * heartCellSize, inner, inner);
            }

            drawHeartFinder(0, 0);
            drawHeartFinder(N - 7, 0);
            drawHeartFinder(0, N - 7);
            ctx.restore();
            if (!isFlower) {
                flattenQrCanvasInk(ctx, heartSize, heartSize, color);
            }
            return;
        }

        var quietModules = 0;
        var cellSize = 8;
        var canvasSize = (N + quietModules * 2) * cellSize;

        canvas.width = canvasSize;
        canvas.height = canvasSize;
        ctx.imageSmoothingEnabled = false;
        ctx.clearRect(0, 0, canvasSize, canvasSize);
        ctx.fillStyle = color;
        for (var row = 0; row < N; row++) {
            for (var col = 0; col < N; col++) {
                if (qr.isDark(row, col)) {
                    ctx.fillRect(
                        (col + quietModules) * cellSize,
                        (row + quietModules) * cellSize,
                        cellSize,
                        cellSize
                    );
                }
            }
        }
        fitMidAutumnQrCanvas(canvas);
    } catch (e) {
        console.warn('Mini QR render err:', e);
    }
}

