// ─── Photo compression utility ──────────────────────────────────────
function checkImageTransparency(img) {
    var c = document.createElement('canvas');
    var w = Math.min(80, img.naturalWidth || img.width || 80);
    var h = Math.min(80, img.naturalHeight || img.height || 80);
    c.width = w;
    c.height = h;
    var ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0, w, h);
    try {
        var data = ctx.getImageData(0, 0, w, h).data;
        var transparentCount = 0;
        for (var i = 3; i < data.length; i += 4) {
            if (data[i] < 240) {
                transparentCount++;
                if (transparentCount > 30) {
                    return true;
                }
            }
        }
    } catch (err) {}
    return false;
}

async function compressImage(file, maxDimension = 1100, quality = 0.82) {
    return new Promise((resolve) => {
        if (!file || !file.type || !file.type.startsWith('image/')) {
            resolve(file);
            return;
        }
        const reader = new FileReader();
        reader.onerror = () => resolve(file);
        reader.onload = function(event) {
            const img = new Image();
            img.onerror = () => resolve(file);
            img.onload = function() {
                let width = img.naturalWidth || img.width;
                let height = img.naturalHeight || img.height;
                const largestSide = Math.max(width, height);
                if (largestSide > maxDimension) {
                    const scale = maxDimension / largestSide;
                    width = Math.max(1, Math.round(width * scale));
                    height = Math.max(1, Math.round(height * scale));
                }

                const isPotentialTransparent = file.type === 'image/png' || file.type === 'image/webp' || /\.(png|webp)$/i.test(file.name || '');
                let isCutout = false;
                if (isPotentialTransparent) {
                    isCutout = checkImageTransparency(img);
                }

                const canvas = document.createElement('canvas');
                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                ctx.drawImage(img, 0, 0, width, height);

                const baseName = String(file.name || 'photo').replace(/\.[^.]+$/, '') || 'photo';
                const dataUrl = canvas.toDataURL(isCutout ? 'image/png' : 'image/jpeg', isCutout ? undefined : quality);

                if (isCutout) {
                    // Giữ định dạng PNG để bảo toàn độ trong suốt tuyệt đối
                    canvas.toBlob((blob) => {
                        const resFile = blob ? new File([blob], baseName + '_cutout.png', { type: 'image/png', lastModified: Date.now() }) : file;
                        resFile._isCutout = true;
                        resFile._dataUrl = dataUrl;
                        resolve(resFile);
                    }, 'image/png');
                } else {
                    // Ảnh thông thường nén JPEG nhẹ, nhanh, mượt
                    canvas.toBlob((blob) => {
                        const resFile = blob ? new File([blob], baseName + '.jpg', { type: 'image/jpeg', lastModified: Date.now() }) : file;
                        resFile._isCutout = false;
                        resFile._dataUrl = dataUrl;
                        resolve(resFile);
                    }, 'image/jpeg', quality);
                }
            };
            img.src = event.target.result;
        };
        reader.readAsDataURL(file);
    });
}

var _selectedPhotoCount = 0;
var _selectedFlyPhotoCount = 0;
var _mediaPreparing = 0;
var _preparedMainPhotos = null;
var _preparedFlyPhotos = null;
var _livePreviewFileUrls = new Map();
function livePreviewObjectUrl(file) {
    if (!file) return '';
    if (file._dataUrl) return file._dataUrl;
    var cached = _livePreviewFileUrls.get(file);
    if (cached) return cached;
    var url = URL.createObjectURL(file);
    _livePreviewFileUrls.set(file, url);
    return url;
}
function clearLivePreviewObjectUrls() {
    _livePreviewFileUrls.forEach(function(url) { URL.revokeObjectURL(url); });
    _livePreviewFileUrls.clear();
}
window.addEventListener('pagehide', clearLivePreviewObjectUrls);

// ─── Handlers for photos ──────────────────────────────────────────
async function handlePhotoUpload(e) {
    clearLivePreviewObjectUrls();
    var files = e.target.files;
    var chk = document.getElementById('use_default_photos');
    if (chk && chk.checked) {
        chk.checked = false;
        toggleDefaultPhotos(false);
    }
    
    if (!files || files.length === 0) {
        _preparedMainPhotos = null;
        _selectedPhotoCount = 0;
        var cutoutsJsonEl = document.getElementById('bouquet_cutouts_json');
        if (cutoutsJsonEl) cutoutsJsonEl.value = '';
        updatePhotoPricing();
        updateTotal();
        if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate();
        return;
    }
    
    var photoLimit = 20;
    var count = Math.min(files.length, photoLimit);
    _selectedPhotoCount = count;
    
    var st = document.getElementById('st-sec-photos');
    if (st) {
        st.textContent = count + ' ảnh';
        st.style.color = '#22c55e';
    }
    
    var info = document.getElementById('photo-count-info');
    if (info) {
        info.textContent = count + ' ảnh đã chọn' + (files.length > photoLimit ? ' (chỉ lấy ' + photoLimit + ' ảnh đầu)' : '');
        info.style.display = 'block';
    }
    
    updatePhotoPricing();
    updateTotal();
    
    _mediaPreparing++;
    try {
        const filesArray = Array.from(files).slice(0, count);
        const processedList = [];
        for (let i = 0; i < filesArray.length; i++) {
            const processed = await compressImage(filesArray[i]);
            processedList.push(processed);
        }

        _preparedMainPhotos = processedList.filter(Boolean);
        try {
            const dt = new DataTransfer();
            _preparedMainPhotos.forEach(cf => dt.items.add(cf));
            document.getElementById('photos').files = dt.files;
        } catch (assignError) {
            // FormData ở bước gửi sẽ dùng _preparedMainPhotos.
        }
        
        var cutoutsJsonEl = document.getElementById('bouquet_cutouts_json');
        if (cutoutsJsonEl) {
            cutoutsJsonEl.value = JSON.stringify(_preparedMainPhotos.map(f => !!f._isCutout));
        }

        var grid = document.getElementById('photo-preview-grid');
        if (grid) {
            grid.innerHTML = '';
            for (var i = 0; i < _preparedMainPhotos.length; i++) {
                var pFile = _preparedMainPhotos[i];
                var isCutout = !!pFile._isCutout;
                var wrap = document.createElement('div');
                wrap.style.cssText = 'position:relative;display:inline-block;margin:5px;vertical-align:top;';
                
                var img = document.createElement('img');
                img.className = 'photo-thumb';
                if (isCutout) {
                    img.style.background = 'repeating-conic-gradient(#e0e0e0 0% 25%, #fff 0% 50%) 50% / 10px 10px';
                    img.style.border = '2px solid #e8589a';
                    img.style.objectFit = 'contain';
                    img.title = 'Ảnh đã tách nền (Cắm vào cánh hoa)';
                } else {
                    img.style.background = '#fff';
                    img.style.border = '3px solid #fff';
                    img.style.borderBottom = '14px solid #fff';
                    img.style.boxShadow = '0 2px 8px rgba(0,0,0,0.15)';
                    img.style.borderRadius = '4px';
                    img.style.objectFit = 'cover';
                    img.title = 'Ảnh thường (Khung Polaroid)';
                }
                img.src = livePreviewObjectUrl(pFile);
                wrap.appendChild(img);

                var badge = document.createElement('span');
                badge.style.cssText = 'position:absolute;bottom:2px;right:2px;font-size:9px;padding:1px 5px;border-radius:5px;font-weight:700;pointer-events:none;';
                if (isCutout) {
                    badge.style.background = '#e8589a';
                    badge.style.color = '#fff';
                    badge.textContent = 'Tách nền';
                } else {
                    badge.style.background = '#4a3e56';
                    badge.style.color = '#fff';
                    badge.textContent = 'Polaroid';
                }
                wrap.appendChild(badge);
                grid.appendChild(wrap);
            }
        }
    } catch (err) {
        if (info) info.textContent = 'Có lỗi xảy ra khi xử lý ảnh: ' + err.message;
        console.error(err);
    } finally {
        _mediaPreparing = Math.max(0, _mediaPreparing - 1);
    }
    
    updatePhotoPricing();
    updateTotal();
    if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate();
}

// ─── Sweet Valentine: mỗi ảnh là một trang sổ, có ô chữ riêng ─────────
var SWEET_MAX_PAGES = 10;
var SWEET_TEXT_SOFT_LIMIT = 280; // dài hơn sẽ tràn khỏi trang sổ
var _sweetTexts = [];
var _sweetThumbs = [];

function sweetSyncFiles() {
    var input = document.getElementById('photos');
    try {
        var dt = new DataTransfer();
        (_preparedMainPhotos || []).forEach(function(f) { dt.items.add(f); });
        input.files = dt.files;
    } catch (e) { /* FormData lúc gửi dùng _preparedMainPhotos */ }
    _selectedPhotoCount = (_preparedMainPhotos || []).length;
    var st = document.getElementById('st-sec-photos');
    if (st) {
        st.textContent = _selectedPhotoCount ? _selectedPhotoCount + ' trang' : 'Chưa thêm';
        st.style.color = _selectedPhotoCount ? '#22c55e' : '#e8589a';
    }
    var btn = document.getElementById('btn-select-photos');
    if (btn) btn.style.display = _selectedPhotoCount >= SWEET_MAX_PAGES ? 'none' : 'block';
    var info = document.getElementById('photo-count-info');
    if (info) {
        info.textContent = _selectedPhotoCount >= SWEET_MAX_PAGES ? 'Đã đủ ' + SWEET_MAX_PAGES + ' trang.' : '';
        info.style.display = _selectedPhotoCount >= SWEET_MAX_PAGES ? 'block' : 'none';
    }
    updatePhotoPricing();
    updateTotal();
}

function sweetPageTexts() {
    return (_preparedMainPhotos || []).map(function(_, i) { return String(_sweetTexts[i] || '').trim(); });
}

function sweetUpdateMessageMirror() {
    // Giữ ô message (ẩn) đồng bộ để các luồng cũ (thông báo, lưu trữ) vẫn có nội dung.
    var msg = document.getElementById('message');
    if (msg) msg.value = sweetPageTexts().map(function(t) { return t.replace(/\s*\n+\s*/g, ' '); }).join('\n');
}

function sweetEscape(str) {
    return String(str).replace(/[&<>"']/g, function(c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; });
}

function renderSweetPages() {
    var wrap = document.getElementById('sweet-pages');
    if (!wrap) return;
    var photos = _preparedMainPhotos || [];
    wrap.innerHTML = photos.map(function(file, i) {
        var text = _sweetTexts[i] || '';
        var len = Array.from(text).length;
        return '<div class="sweet-page" data-index="' + i + '">' +
            '<div class="sweet-page__img"><img src="' + _sweetThumbs[i] + '" alt="Ảnh trang ' + (i + 1) + '"><span class="sweet-page__no">' + (i + 1) + '</span></div>' +
            '<div class="sweet-page__body">' +
                '<div class="sweet-page__head"><span class="sweet-page__title">Trang ' + (i + 1) + '</span>' +
                    '<span class="sweet-page__tools">' +
                        '<button type="button" onclick="sweetMovePage(' + i + ',-1)" aria-label="Đưa trang ' + (i + 1) + ' lên"' + (i === 0 ? ' disabled' : '') + '>↑</button>' +
                        '<button type="button" onclick="sweetMovePage(' + i + ',1)" aria-label="Đưa trang ' + (i + 1) + ' xuống"' + (i === photos.length - 1 ? ' disabled' : '') + '>↓</button>' +
                        '<button type="button" class="sweet-page__del" onclick="sweetRemovePage(' + i + ')" aria-label="Xóa trang ' + (i + 1) + '">✕</button>' +
                    '</span></div>' +
                '<textarea name="sweet_page_texts[]" maxlength="600" placeholder="Lời nhắn cho ảnh này… VD: Giữa cả một cánh đồng hoa, người anh thấy đẹp nhất vẫn là em 💞" oninput="sweetOnText(' + i + ', this)">' + sweetEscape(text) + '</textarea>' +
                '<span class="sweet-page__count' + (len > SWEET_TEXT_SOFT_LIMIT ? ' is-long' : '') + '">' + len + ' ký tự' + (len > SWEET_TEXT_SOFT_LIMIT ? ' · hơi dài, chữ có thể tràn trang' : '') + '</span>' +
            '</div>' +
        '</div>';
    }).join('');
    sweetUpdateMessageMirror();
}

var _sweetPreviewTimer = 0;
function sweetOnText(i, el) {
    _sweetTexts[i] = el.value;
    var len = Array.from(el.value).length;
    var counter = el.parentNode.querySelector('.sweet-page__count');
    if (counter) {
        counter.textContent = len + ' ký tự' + (len > SWEET_TEXT_SOFT_LIMIT ? ' · hơi dài, chữ có thể tràn trang' : '');
        counter.classList.toggle('is-long', len > SWEET_TEXT_SOFT_LIMIT);
    }
    sweetUpdateMessageMirror();
    clearTimeout(_sweetPreviewTimer);
    _sweetPreviewTimer = setTimeout(function() { if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate(); }, 400);
}

function sweetMovePage(i, dir) {
    var j = i + dir, photos = _preparedMainPhotos || [];
    if (j < 0 || j >= photos.length) return;
    [photos[i], photos[j]] = [photos[j], photos[i]];
    [_sweetTexts[i], _sweetTexts[j]] = [_sweetTexts[j], _sweetTexts[i]];
    [_sweetThumbs[i], _sweetThumbs[j]] = [_sweetThumbs[j], _sweetThumbs[i]];
    sweetSyncFiles();
    renderSweetPages();
    if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate();
}

function sweetRemovePage(i) {
    var photos = _preparedMainPhotos || [];
    if (!photos[i]) return;
    var hasText = String(_sweetTexts[i] || '').trim() !== '';
    if (hasText && !confirm('Xóa trang ' + (i + 1) + ' cùng lời nhắn của trang này?')) return;
    URL.revokeObjectURL(_sweetThumbs[i]);
    photos.splice(i, 1);
    _sweetTexts.splice(i, 1);
    _sweetThumbs.splice(i, 1);
    sweetSyncFiles();
    renderSweetPages();
    if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate();
}

async function handleSweetPhotoUpload(e) {
    var input = e.target;
    // Lấy danh sách file mới trước khi sweetSyncFiles() ghi đè input.files.
    var picked = Array.from(input.files || []).filter(function(f) { return !(_preparedMainPhotos || []).includes(f); });
    var room = SWEET_MAX_PAGES - (_preparedMainPhotos || []).length;
    if (!picked.length) { sweetSyncFiles(); return; }
    if (room <= 0) { sweetSyncFiles(); alert('Cuốn sổ đã đủ ' + SWEET_MAX_PAGES + ' trang.'); return; }
    var extra = picked.length - room;
    picked = picked.slice(0, room);
    _mediaPreparing++;
    try {
        var compressed = (await Promise.all(picked.map(function(f) { return compressImage(f); }))).filter(Boolean);
        _preparedMainPhotos = (_preparedMainPhotos || []).concat(compressed);
        compressed.forEach(function(f) { _sweetTexts.push(''); _sweetThumbs.push(URL.createObjectURL(f)); });
    } catch (err) {
        console.error(err);
        alert('Có lỗi khi xử lý ảnh: ' + err.message);
    } finally {
        _mediaPreparing = Math.max(0, _mediaPreparing - 1);
    }
    sweetSyncFiles();
    renderSweetPages();
    if (extra > 0) alert('Chỉ thêm được ' + room + ' ảnh nữa (tối đa ' + SWEET_MAX_PAGES + ' trang).');
    if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate();
    // Focus ô chữ của trang mới đầu tiên để viết ngay.
    var first = document.querySelector('.sweet-page[data-index="' + (_preparedMainPhotos.length - picked.length) + '"] textarea');
    if (first) first.focus({ preventScroll: false });
}

function toggleDefaultPhotos(checked) {
    var lbl = document.getElementById('lbl-default-photos');
    var btn = document.getElementById('btn-select-photos');
    if (checked) {
        _selectedPhotoCount = 0;
        lbl.style.borderColor = '#22c55e';
        lbl.style.color = '#22c55e';
        lbl.style.background = '#e8f5e9';
        document.getElementById('photos').value = '';
        _preparedMainPhotos = [];
        var dt = new DataTransfer();
        document.getElementById('photos').files = dt.files;
        
        document.getElementById('photo-preview-grid').innerHTML = '<img class="photo-thumb" src="womens-day/assets/images/icons/couple.png" style="opacity:0.8; object-fit:contain; background:#3d3551;"><img class="photo-thumb" src="womens-day/assets/images/characters/bearflower.png" style="opacity:0.8; object-fit:contain; background:#3d3551;">';
        var st = document.getElementById('st-sec-photos');
        st.textContent = 'Mặc định (Miễn phí)';
        st.style.color = '#22c55e';
        document.getElementById('photo-count-info').style.display = 'none';
        if (btn) btn.style.display = 'none';
    } else {
        lbl.style.borderColor = '#ddd';
        lbl.style.color = '#555';
        lbl.style.background = '#fff';
        document.getElementById('photo-preview-grid').innerHTML = '';
        var st = document.getElementById('st-sec-photos');
        st.textContent = 'Chưa thêm';
        st.style.color = '#e8589a';
        if (btn) btn.style.display = 'block';
    }
    updatePhotoPricing();
    updateTotal();
    if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate();
}

function updatePhotoPricing() {
    var urlParams = new URLSearchParams(window.location.search);
    var tplId = urlParams.get('id') || '69';
    var NO_PHOTO_TEMPLATES = ['8', '9', '27', '28', '37', '44', '45', '49', '54', '62', '63', '64', '67'];
    if (NO_PHOTO_TEMPLATES.indexOf(String(tplId)) !== -1) {
        var pr0 = document.getElementById('pr-images') || document.getElementById('pr-photos');
        if (pr0) { pr0.textContent = '0đ'; pr0.style.color = '#7a7090'; }
        return;
    }
    var count = _selectedPhotoCount;
    var useDefault = document.getElementById('use_default_photos') && document.getElementById('use_default_photos').checked;
    var pr = document.getElementById('pr-images') || document.getElementById('pr-photos');
    if (pr) {
        if (useDefault) {
            pr.textContent = 'Miễn phí';
            pr.style.color = '#22c55e';
        } else if (count > 0) {
            var unitPrice = (typeof PHOTO_UNIT_PRICE !== 'undefined') ? PHOTO_UNIT_PRICE : 5000;
            if (unitPrice === 0) {
                pr.textContent = 'Miễn phí';
                pr.style.color = '#22c55e';
            } else {
                pr.textContent = (count * unitPrice).toLocaleString('vi-VN') + 'đ';
                pr.style.color = '#e8589a';
            }
        } else {
            pr.textContent = '—';
            pr.style.color = '#ccc';
        }
    }
}

// ─── Fly photos upload ────────────────────────────────────────────
async function handleFlyPhotoUpload(e) {
    clearLivePreviewObjectUrls();
    var files = e.target.files;
    if (!files || files.length === 0) return;
    
    var info = document.getElementById('fly-count-info');
    if (info) {
        info.style.display = 'block';
        info.textContent = 'Đang xử lý ảnh, vui lòng chờ...';
    }
    
    _mediaPreparing++;
    try {
        var count = Math.min(files.length, 20);
        const compressedList = [];
        for (let i = 0; i < count; i++) {
            let compressed = await compressImage(files[i]);
            if (compressed) {
                compressedList.push(compressed);
            }
        }
        _preparedFlyPhotos = compressedList;
        
        try {
            const dt = new DataTransfer();
            compressedList.forEach(function(file) { dt.items.add(file); });
            if (document.getElementById('fly_photos')) {
                document.getElementById('fly_photos').files = dt.files;
            }
            files = dt.files;
        } catch(err) {
            console.warn("Could not set files on input", err);
            files = compressedList;
        }
        
        var grid = document.getElementById('fly-preview-grid');
        if (grid) {
            grid.innerHTML = '';
            for (var i=0; i<count; i++) {
                var img = document.createElement('img');
                img.className = 'photo-thumb';
                img.src = URL.createObjectURL(files[i]);
                grid.appendChild(img);
            }
        }
        var st = document.getElementById('st-sec-fly');
        if (st) {
            if (count > 0) {
                st.textContent = count + ' ảnh';
                st.style.color = '#22c55e';
                if (info) {
                    info.textContent = count + ' ảnh bay đã chọn' + (files.length>20?' (chỉ lấy 20 ảnh đầu)':'');
                    info.style.display = 'block';
                }
            } else {
                st.textContent = 'Chưa thêm';
                st.style.color = '#a79fb8';
                if (info) info.style.display = 'none';
            }
        }
    } catch (err) {
        if (info) info.textContent = 'Có lỗi xảy ra khi xử lý ảnh: ' + err.message;
        console.error(err);
    } finally {
        _mediaPreparing = Math.max(0, _mediaPreparing - 1);
    }

    if (typeof updateFlyPricing === 'function') updateFlyPricing();
    if (typeof updateTotal === 'function') updateTotal();
    if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate();
}

function updateFlyPricing() {
    var files = document.getElementById('fly_photos') ? document.getElementById('fly_photos').files : null;
    var count = Math.min(files ? files.length : 0, 20);
    var unitPrice = 5000;
    var pr = document.getElementById('pr-fly');
    if (!pr) return;
    if (count > 0 && unitPrice === 0) {
        pr.textContent = 'Miễn phí';
        pr.style.color = '#22c55e';
    } else if (count > 0) {
        pr.textContent = (count * unitPrice).toLocaleString('vi-VN') + 'đ';
        pr.style.color = '#e8589a';
    } else {
        pr.textContent = '—';
        pr.style.color = '#ccc';
    }
}

// ─── Music tab ────────────────────────────────────────────────────
function switchMusicTab(tab) {
    var sourceInput = document.getElementById('music_source_type');
    var uploadInput = document.getElementById('music_upload');
    if (tab === 'preset') {
        document.getElementById('panel-preset').style.display='';
        document.getElementById('panel-upload').style.display='none';
        document.getElementById('tab-preset').style.background='#e8589a';
        document.getElementById('tab-preset').style.color='#fff';
        document.getElementById('tab-upload').style.background='#fff';
        document.getElementById('tab-upload').style.color='#7a7090';
        if (uploadInput) {
            uploadInput.value = '';
            uploadInput.disabled = true;
        }
        if (sourceInput) sourceInput.value = 'preset';
        var selectedCard = document.querySelector('.music-card.selected') || document.querySelector('.music-card--original') || document.querySelector('.music-card');
        if (selectedCard) selectMusicCard(selectedCard);
    } else {
        document.getElementById('panel-preset').style.display='none';
        document.getElementById('panel-upload').style.display='';
        document.getElementById('tab-upload').style.background='#e8589a';
        document.getElementById('tab-upload').style.color='#fff';
        document.getElementById('tab-preset').style.background='#fff';
        document.getElementById('tab-preset').style.color='#7a7090';
        if (uploadInput) uploadInput.disabled = false;
        if (sourceInput) sourceInput.value = 'upload';
        document.querySelectorAll('.music-card').forEach(function(card) { card.classList.remove('selected'); });
        document.getElementById('music_url').value = '';
        document.getElementById('music_song_id').value = '';
        document.getElementById('st-sec-music').textContent = uploadInput && uploadInput.files.length ? 'File riêng' : 'Chưa chọn file';
        document.getElementById('st-sec-music').style.color = uploadInput && uploadInput.files.length ? '#22c55e' : '#7a7090';
        updateTotal();
        if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate();
    }
}

var _previewAudio = null;
var _activePreviewBtn = null;

function selectMusicCard(card) {
    if (_activePreviewBtn) { _activePreviewBtn.textContent='▶'; _activePreviewBtn.classList.remove('playing'); }
    if (_previewAudio) { _previewAudio.pause(); }
    _activePreviewBtn = null;
    document.querySelectorAll('.music-card').forEach(c => c.classList.remove('selected'));
    card.classList.add('selected');
    var uploadInput = document.getElementById('music_upload');
    if (uploadInput) {
        uploadInput.value = '';
        uploadInput.disabled = true;
    }
    document.getElementById('music_source_type').value = 'preset';
    document.getElementById('music_url').value = card.getAttribute('data-value');
    document.getElementById('music_song_id').value = card.getAttribute('data-song-id') || '';
    var songName = card.querySelector('.music-card-name');
    document.getElementById('st-sec-music').textContent = card.getAttribute('data-original') === '1'
        ? 'Nhạc gốc'
        : (songName ? songName.textContent.trim() : 'Đã chọn');
    document.getElementById('st-sec-music').style.color = '#22c55e';
    updateTotal();
    if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate();
}

async function handleCustomMusicChange() {
    var uploadInput = document.getElementById('music_upload');
    var hasFile = !!(uploadInput && uploadInput.files && uploadInput.files[0]);
    document.getElementById('music_source_type').value = 'upload';
    document.getElementById('music_url').value = '';
    document.getElementById('music_song_id').value = '';
    document.querySelectorAll('.music-card').forEach(function(card) { card.classList.remove('selected'); });
    if (_previewAudio) _previewAudio.pause();
    if (_activePreviewBtn) {
        _activePreviewBtn.textContent = '▶';
        _activePreviewBtn.classList.remove('playing');
        _activePreviewBtn = null;
    }
    var statusEl = document.getElementById('st-sec-music');
    if (!hasFile) {
        statusEl.textContent = 'Chưa chọn file';
        statusEl.style.color = '#7a7090';
        updateTotal();
        return;
    }

    var selectedFile = uploadInput.files[0];
    // Video (mp4/mov/m4v/webm/3gp) và định dạng iPhone cũ không phát được (ogg/opus/flac/weba)
    // được tách/chuyển thành WAV ngay trên trình duyệt để phát được trên mọi máy.
    var isMp4 = /\.(mp4|m4v|mov|webm|3gp|ogg|oga|opus|flac|weba)$/i.test(selectedFile.name) || /^video\//i.test(selectedFile.type || '');
    if (!isMp4) {
        statusEl.textContent = selectedFile.name;
        statusEl.style.color = '#22c55e';
        updateTotal();
        if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate();
        return;
    }

    _mediaPreparing++;
    statusEl.textContent = 'Đang tách âm thanh từ video...';
    statusEl.style.color = '#f59e0b';
    try {
        var audioOnlyFile = await extractAudioFromMp4(selectedFile);
        var transfer = new DataTransfer();
        transfer.items.add(audioOnlyFile);
        uploadInput.files = transfer.files;
        statusEl.textContent = audioOnlyFile.name + ' · Đã tách âm thanh';
        statusEl.style.color = '#22c55e';
        showToast('Đã tách âm thanh khỏi video. Bạn có thể tạo quà ngay.', 'success');
    } catch (error) {
        if (SERVER_CONVERTS_AUDIO && selectedFile.size <= 100 * 1024 * 1024) {
            // Máy chủ có ffmpeg: giữ tệp gốc, máy chủ sẽ tách/chuyển sang m4a khi tạo quà.
            statusEl.textContent = selectedFile.name + ' · Máy chủ sẽ xử lý âm thanh';
            statusEl.style.color = '#22c55e';
            return;
        }
        uploadInput.value = '';
        statusEl.textContent = 'Không thể tách âm thanh';
        statusEl.style.color = '#dc2626';
        showToast(error && error.message ? error.message : 'Không thể đọc âm thanh trong video. Hãy chọn tệp MP3 hoặc M4A.', 'error');
    } finally {
        _mediaPreparing = Math.max(0, _mediaPreparing - 1);
        updateTotal();
        if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate();
    }
}

var SERVER_CONVERTS_AUDIO = false;

async function extractAudioFromMp4(file) {
    var AudioContextClass = window.AudioContext || window.webkitAudioContext;
    var OfflineAudioContextClass = window.OfflineAudioContext || window.webkitOfflineAudioContext;
    if (!AudioContextClass || !OfflineAudioContextClass || typeof DataTransfer === 'undefined') {
        throw new Error('Trình duyệt này chưa hỗ trợ tách âm thanh. Hãy chọn tệp MP3 hoặc M4A.');
    }

    var context = new AudioContextClass();
    var decoded;
    try {
        var sourceBuffer = await file.arrayBuffer();
        decoded = await context.decodeAudioData(sourceBuffer.slice(0));
    } catch (decodeError) {
        throw new Error('Video không có luồng âm thanh tương thích. Hãy chọn video MP4 khác hoặc tệp MP3/M4A.');
    } finally {
        if (context && typeof context.close === 'function') context.close().catch(function() {});
    }

    if (!decoded || !isFinite(decoded.duration) || decoded.duration <= 0) {
        throw new Error('Không tìm thấy âm thanh trong video đã chọn.');
    }

    // PCM 16-bit mono giữ âm thanh tương thích trên mọi mẫu quà. Tự giảm tần
    // số lấy mẫu khi cần để tệp sau tách luôn nằm dưới giới hạn 20 MB.
    var maxBytes = 10 * 1024 * 1024;
    var maximumRateForSize = Math.floor((maxBytes - 44) / (decoded.duration * 2));
    var targetRate = Math.min(32000, decoded.sampleRate, maximumRateForSize);
    if (targetRate < 12000) {
        throw new Error('Video quá dài để tách âm thanh. Hãy cắt ngắn video hoặc chọn tệp MP3/M4A dưới 20 MB.');
    }
    targetRate = Math.max(12000, Math.floor(targetRate));
    var frameCount = Math.max(1, Math.ceil(decoded.duration * targetRate));
    var offline = new OfflineAudioContextClass(1, frameCount, targetRate);
    var source = offline.createBufferSource();
    source.buffer = decoded;
    source.connect(offline.destination);
    source.start(0);
    var rendered = await offline.startRendering();
    var wavBlob = encodeMonoWav(rendered.getChannelData(0), rendered.sampleRate);
    if (wavBlob.size > 10 * 1024 * 1024) {
        throw new Error('Âm thanh sau khi tách còn quá lớn. Hãy dùng video ngắn hơn.');
    }
    var outputName = file.name.replace(/\.mp4$/i, '') + '-audio.wav';
    return new File([wavBlob], outputName, { type: 'audio/wav', lastModified: Date.now() });
}

function encodeMonoWav(samples, sampleRate) {
    var buffer = new ArrayBuffer(44 + samples.length * 2);
    var view = new DataView(buffer);
    function writeText(offset, value) {
        for (var i = 0; i < value.length; i++) view.setUint8(offset + i, value.charCodeAt(i));
    }
    writeText(0, 'RIFF');
    view.setUint32(4, 36 + samples.length * 2, true);
    writeText(8, 'WAVE');
    writeText(12, 'fmt ');
    view.setUint32(16, 16, true);
    view.setUint16(20, 1, true);
    view.setUint16(22, 1, true);
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * 2, true);
    view.setUint16(32, 2, true);
    view.setUint16(34, 16, true);
    writeText(36, 'data');
    view.setUint32(40, samples.length * 2, true);
    for (var i = 0, offset = 44; i < samples.length; i++, offset += 2) {
        var sample = Math.max(-1, Math.min(1, samples[i]));
        view.setInt16(offset, sample < 0 ? sample * 32768 : sample * 32767, true);
    }
    return new Blob([buffer], { type: 'audio/wav' });
}

function previewMusic(e, src, btn) {
    e.stopPropagation();
    var card = btn.closest('.music-card');
    if (card) selectMusicCard(card);
    
    // Stop all audio in preview iframe while playing builder preview
    var frame = document.getElementById('gift-live-preview');
    if (frame && frame.contentWindow) {
        try {
            frame.contentWindow.postMessage({ type: 'DG_STOP_AUDIO' }, '*');
            frame.contentWindow.postMessage({ type: 'DG_PAUSE_AUDIO' }, '*');
        } catch(err) {}
    }
    if (!_previewAudio) _previewAudio = document.getElementById('music-preview-player');
    if (_activePreviewBtn && _activePreviewBtn !== btn) {
        _activePreviewBtn.textContent='▶';
        _activePreviewBtn.classList.remove('playing');
    }
    var resolvedSrc = '';
    try { resolvedSrc = new URL(src, document.baseURI).href; } catch (error) { resolvedSrc = src; }
    if (_previewAudio.currentSrc === resolvedSrc && !_previewAudio.paused) {
        _previewAudio.pause();
        btn.textContent='▶'; btn.classList.remove('playing'); _activePreviewBtn=null;
    } else {
        _previewAudio.src = resolvedSrc;
        _previewAudio.volume=0.7;
        _previewAudio.preload='auto';
        _previewAudio.setAttribute('playsinline', '');
        _previewAudio.load();
        btn.textContent='■'; btn.classList.add('playing'); _activePreviewBtn=btn;
        var resetPreviewButton = function(message) {
            btn.textContent='▶';
            btn.classList.remove('playing');
            if (_activePreviewBtn === btn) _activePreviewBtn=null;
            if (message && typeof showToast === 'function') showToast(message, 'error');
        };
        _previewAudio.play().catch(function() {
            resetPreviewButton('Không thể phát bài này. Vui lòng chọn bài khác hoặc báo quản trị viên kiểm tra tệp nhạc.');
        });
        _previewAudio.onerror = function() {
            resetPreviewButton('Tệp nhạc này hiện không tải được. Vui lòng chọn bài khác.');
        };
        _previewAudio.onended = () => { btn.textContent='▶'; btn.classList.remove('playing'); _activePreviewBtn=null; };
    }
}

function showMoreSongs() {
    document.querySelectorAll('#music-card-grid .music-card').forEach(c => c.style.display='');
    document.getElementById('show-more-wrap').style.display='none';
}

// ─── Duration selection ───────────────────────────────────────────
function selectDuration(val, el) {
    ['dur-free','dur-year','dur-life'].forEach(id => {
        var el2 = document.getElementById(id);
        if (el2) el2.classList.remove('sel');
    });
    el.classList.add('sel');
    el.querySelector('input').checked = true;
    var prices = {free_15mins:'Miễn phí',free_15days:'Miễn phí',one_year:'30.000đ',lifetime:'60.000đ'};
    var pr = document.getElementById('pr-duration');
    pr.textContent = prices[val];
    pr.style.color = val==='free_15days' ? '#22c55e' : '#e8589a';
    updateTotal();
}

// ─── Tip selection ─────────────────────────────────────────────────
function selectTip(amount, el) {
    document.querySelectorAll('.tip-btn').forEach(b => b.classList.remove('sel'));
    el.classList.add('sel');
    document.getElementById('tip_amount_val').value = amount;
    var pr = document.getElementById('pr-tip');
    pr.textContent = amount ? amount.toLocaleString('vi-VN')+'đ' : '0đ';
    pr.style.color = amount ? '#e8589a' : '#ccc';
