}

function toggleCustomTip() {
    var w = document.getElementById('custom-tip-wrap');
    w.style.display = w.style.display==='none' ? 'block' : 'none';
    document.querySelectorAll('.tip-btn').forEach(b => b.classList.remove('sel'));
    document.getElementById('tip-custom-btn').classList.add('sel');
}

function applyCustomTip() {
    var v = parseInt(document.getElementById('custom_tip_input').value) || 0;
    document.getElementById('tip_amount_val').value = v;
    var pr = document.getElementById('pr-tip');
    pr.textContent = v ? v.toLocaleString('vi-VN')+'đ' : '0đ';
    pr.style.color = v ? '#e8589a' : '#ccc';
    updateTotal();
}

// ─── Voucher ──────────────────────────────────────────────────────
var _voucherDiscount = 0;
function toggleVoucher() {
    var body = document.getElementById('voucher-body');
    var arrow = document.getElementById('voucher-arrow');
    if (body.classList.contains('open')) {
        body.classList.remove('open');
        arrow.textContent = '›';
    } else {
        body.classList.add('open');
        arrow.textContent = '∨';
    }
}

function applyVoucher() {
    var code = document.getElementById('voucher_input').value.trim().toUpperCase();
    var msg = document.getElementById('voucher-msg');
    msg.style.display = 'block';
    
    if (!code) {
        msg.textContent = '❌ Vui lòng nhập mã voucher';
        msg.style.color = '#dc2626';
        return;
    }

    var dur = document.querySelector('input[name="duration"]:checked');
    var durPrice = 0;
    if (dur) {
        if (dur.value==='one_year') durPrice=30000;
        else if (dur.value==='lifetime') durPrice=60000;
    }
    
    var templatePrice = 50000;
    
    var passToggle = document.getElementById('pass_toggle');
    var passPrice = 0;
    
    var qrToggle = document.getElementById('enable_qr');
    var qrPrice = (qrToggle && qrToggle.checked) ? 10000 : 0;
    
    var musicUploadEl = document.getElementById('music_upload');
    var customMusicPrice = (musicUploadEl && musicUploadEl.files && musicUploadEl.files.length > 0) ? 10000 : 0;
    
    var mainPhotoCount = _selectedPhotoCount > 0 ? _selectedPhotoCount : Math.min(document.getElementById('photos')?.files?.length || 0, 20);
    var flyPhotoCount = Math.min(document.getElementById('fly_photos')?.files?.length || 0, 20);
    var PHOTO_UNIT_PRICE = 5000;
    var imagePrice = (mainPhotoCount + flyPhotoCount) * PHOTO_UNIT_PRICE;
    var total_for_discount = templatePrice + imagePrice + durPrice + passPrice + qrPrice + customMusicPrice;

    msg.textContent = 'Đang kiểm tra mã...';
    msg.style.color = '#7a7090';

    fetch('api_check_voucher.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': "9f55332385c56c5884765d6c4ebb06c17ebcb72568e69bfe19c721f3da125428" },
        body: JSON.stringify({ code: code, total: total_for_discount })
    })
    .then(r => r.json())
    .then(data => {
        if (data.success) {
            _voucherDiscount = data.discount;
            document.getElementById('hidden_voucher_code').value = code;
            msg.textContent = data.message;
            msg.style.color = '#22c55e';
            document.getElementById('pr-voucher').textContent = '-' + data.discount.toLocaleString('vi-VN') + 'đ';
            document.getElementById('pr-voucher').style.color = '#22c55e';
            updateTotal();
        } else {
            _voucherDiscount = 0;
            document.getElementById('hidden_voucher_code').value = '';
            msg.textContent = '❌ ' + data.message;
            msg.style.color = '#dc2626';
            document.getElementById('pr-voucher').textContent = '—';
            document.getElementById('pr-voucher').style.color = '#ccc';
            updateTotal();
        }
    })
    .catch(err => {
        msg.textContent = '❌ Có lỗi xảy ra, vui lòng thử lại';
        msg.style.color = '#dc2626';
    });
}

// ─── Total calculation ────────────────────────────────────────────
function updateTotal() {
    var dur = document.querySelector('input[name="duration"]:checked');
    var durPrice = 0;
    if (dur) {
        if (dur.value==='one_year') durPrice=30000;
        else if (dur.value==='lifetime') durPrice=60000;
    }
    var tip = parseInt(document.getElementById('tip_amount_val').value)||0;
    
    // Dynamic template price from active template
    var templatePrice = 50000;
    var tplId = (new URLSearchParams(window.location.search)).get('id') || '69';
    if (window.DG_TEMPLATES && window.DG_TEMPLATES[tplId]) {
        var pStr = String(window.DG_TEMPLATES[tplId].price || '');
        if (pStr.toLowerCase().indexOf('miễn phí') !== -1 || pStr.toLowerCase().indexOf('free') !== -1 || pStr === '0' || pStr === '0đ') {
            templatePrice = 0;
        } else {
            var num = parseInt(pStr.replace(/[^0-9]/g, ''), 10);
            if (!isNaN(num)) templatePrice = num;
        }
    } else {
        var prTemplate = document.getElementById('pr-template');
        if (prTemplate) {
            var pStr = prTemplate.textContent || '';
            if (pStr.toLowerCase().indexOf('miễn phí') !== -1 || pStr.toLowerCase().indexOf('free') !== -1 || pStr === '0' || pStr === '0đ') {
                templatePrice = 0;
            } else {
                var num = parseInt(pStr.replace(/[^0-9]/g, ''), 10);
                if (!isNaN(num)) templatePrice = num;
            }
        }
    }
    
    var passToggle = document.getElementById('pass_toggle');
    var passPrice = 0; // Password is Free
    
    var qrToggle = document.getElementById('enable_qr');
    var qrPrice = (qrToggle && qrToggle.checked) ? 10000 : 0;
    
    var musicUploadEl = document.getElementById('music_upload');
    var customMusicPrice = (musicUploadEl && musicUploadEl.files && musicUploadEl.files.length > 0) ? 10000 : 0;

    var useDefault = document.getElementById('use_default_photos') && document.getElementById('use_default_photos').checked;
    var imagePrice = 0;
    if (!useDefault) {
        var mainPhotoCount = _selectedPhotoCount > 0 ? _selectedPhotoCount : Math.min(document.getElementById('photos')?.files?.length || 0, 20);
        var flyPhotoCount = Math.min(document.getElementById('fly_photos')?.files?.length || 0, 20);
        var PHOTO_UNIT_PRICE = 5000;
        imagePrice = (mainPhotoCount + flyPhotoCount) * PHOTO_UNIT_PRICE;
    }
    var prImages = document.getElementById('pr-images');
    if (prImages) {
        if (useDefault) {
            prImages.textContent = 'Miễn phí';
            prImages.style.color = '#22c55e';
        } else {
            prImages.textContent = imagePrice > 0 ? imagePrice.toLocaleString('vi-VN') + 'đ' : '—';
            prImages.style.color = imagePrice > 0 ? '#e8589a' : '#ccc';
        }
    }
    
    var prCustomMusic = document.getElementById('pr-custom-music');
    if (prCustomMusic) {
        if (customMusicPrice > 0) {
            prCustomMusic.textContent = customMusicPrice.toLocaleString('vi-VN') + 'đ';
            prCustomMusic.style.color = '#e8589a';
            prCustomMusic.className = 'price-val';
        } else {
            prCustomMusic.textContent = 'Miễn phí';
            prCustomMusic.style.color = '#22c55e';
            prCustomMusic.className = 'price-val free';
        }
    }
    
    var total = templatePrice + imagePrice + durPrice + tip + passPrice + qrPrice + customMusicPrice - _voucherDiscount;
    if (total < 0) total = 0;
    var display = document.getElementById('total_price_display');
    display.textContent = total===0 ? 'Miễn phí' : total.toLocaleString('vi-VN')+'đ';
    display.style.color = total===0 ? '#22c55e' : '#e8589a';
    
    // Keep hidden input in sync so proceedToPayment can read it
    var hidden = document.getElementById('total_price_hidden');
    if (!hidden) {
        hidden = document.createElement('input');
        hidden.type = 'hidden';
        hidden.id = 'total_price_hidden';
        hidden.name = 'total_price_hidden';
        document.getElementById('giftForm').appendChild(hidden);
    }
    hidden.value = total;

    // Sync sticky bottom bar (mobile)
    var stickyAmt = document.getElementById('sticky-total-amount');
    if (stickyAmt) {
        stickyAmt.textContent = total === 0 ? 'Miễn phí' : total.toLocaleString('vi-VN') + 'đ';
        stickyAmt.style.color = total === 0 ? '#22c55e' : '#e8589a';
    }
}

// ─── Checkout flow ────────────────────────────────────────────────
function handleCheckout() {
    fetch('/api/me', { credentials: 'same-origin' })
        .then(function (r) { return r.json(); })
        .then(function (res) {
            if (!res || !res.logged_in || !res.user) {
                var redirect = encodeURIComponent(window.location.pathname + window.location.search);
                window.location.href = '/login.html?redirect=' + redirect;
                return;
            }
            proceedCheckout();
        })
        .catch(function () {
            var redirect = encodeURIComponent(window.location.pathname + window.location.search);
            window.location.href = '/login.html?redirect=' + redirect;
        });
}

function proceedCheckout() {
    var v3RecInput = document.getElementById('v3_recipient_name');
    var recInput = document.getElementById('recipient_name');
    if (v3RecInput && recInput && v3RecInput.value.trim() !== '') {
        recInput.value = v3RecInput.value.trim();
    }
    var name = recInput ? recInput.value.trim() : '';
    if (!name) {
        var targetSection = "sec-v3";
        switchSection(targetSection, document.querySelector('[data-section="' + targetSection + '"]'));
        if (v3RecInput && !empty_el(v3RecInput)) {
            v3RecInput.focus();
        } else if (recInput) {
            recInput.focus();
        }
        showToast('Vui lòng nhập tên người nhận quà!', 'error');
        return;
    }

    var templateSlug = "mon-qua-nho-2010";
    if (templateSlug === 'valentine') {
        var pinValue = document.getElementById('password_value')?.value || '';
        if (!/^\d{4}$/.test(pinValue)) {
            switchSection('sec-password', document.querySelector('[data-section="sec-password"]'));
            document.getElementById('password_value')?.focus();
            showToast('Mật khẩu Valentine phải có đúng 4 chữ số.', 'error');
            return;
        }
    }
    if (templateSlug !== 'christmas' && templateSlug !== 'troll-ny' && templateSlug !== 'valentine' && templateSlug !== 'mon-qua-nho-2010') {
        var photos = document.getElementById('photos') ? document.getElementById('photos').files : null;
        var flyPhotos = document.getElementById('fly_photos') ? document.getElementById('fly_photos').files : null;
        var useDefault = document.getElementById('use_default_photos') && document.getElementById('use_default_photos').checked;
        if ((!photos || photos.length === 0) && (!flyPhotos || flyPhotos.length === 0) && !useDefault) {
            openModal('modal-incomplete');
            return;
        }
    }

    proceedToPayment();
}
function empty_el(el) { return !el; }

