var v3SingleImageBlobUrls = {};

function toggleV3SceneCard(checkbox) {
    var card = checkbox.closest('.v3-scene-card');
    if (!card) return;
    var enabled = !!checkbox.checked;
    card.classList.toggle('is-disabled', !enabled);
    var badge = card.querySelector('.v3-scene-status-badge');
    if (badge) {
        badge.textContent = enabled ? 'Đang bật' : 'Đang tắt';
        badge.style.color = enabled ? '#16a34a' : '#9ca3af';
    }
}

function filterV3SceneCards(targetId, btn) {
    document.querySelectorAll('#v3SceneFilterBar .v3-filter-pill').forEach(function(b) {
        b.classList.toggle('active', b === btn);
    });
    document.querySelectorAll('#sec-v3 .v3-scene-card').forEach(function(card) {
        if (targetId === 'all' || card.id === targetId) {
            card.style.display = '';
        } else {
            card.style.display = 'none';
        }
    });
}

function applyV3OccasionPreset(presetKey, btn) {
    var preset = v3OccasionPresets && v3OccasionPresets[presetKey];
    if (!preset) return;
    document.querySelectorAll('#v3OccasionBar .v3-occasion-btn').forEach(function(b) {
        b.classList.toggle('active', b === btn);
    });
    var badgeText = document.getElementById('v3OccasionBadgeText');
    if (badgeText && preset.badge) {
        badgeText.textContent = preset.badge;
    }
    var valuesObj = preset.values || preset;
    Object.keys(valuesObj).forEach(function(key) {
        if (key === 'label' || key === 'badge') return;
        var el = document.getElementById('v3_' + key.replace(/[^a-z0-9_]/gi, '_'));
        if (!el) return;
        var val = valuesObj[key];
        if (el.type === 'checkbox') {
            el.checked = (String(val) === '1' || val === true);
            if (el.classList.contains('v3-scene-toggle')) {
                toggleV3SceneCard(el);
            }
        } else {
            el.value = val;
            if (key === 'recipient_name') {
                var recEl = document.getElementById('recipient_name');
                if (recEl) recEl.value = val;
            }
        }
    });
    if (typeof showToast === 'function') {
        showToast('Đã áp dụng bộ nội dung: ' + (preset.label || presetKey), 'success');
    }
    sendLivePreviewUpdate();
}

function handleV3SingleImageChange(fileInput) {
    var key = fileInput.getAttribute('data-v3-key');
    var previewId = fileInput.getAttribute('data-preview-id');
    var clearId = fileInput.getAttribute('data-clear-id');
    var hiddenInput = document.getElementById('v3_' + key.replace(/[^a-z0-9_]/gi, '_'));
    var previewImg = previewId ? document.getElementById(previewId) : null;
    var clearBtn = clearId ? document.getElementById(clearId) : null;

    if (v3SingleImageBlobUrls[key]) {
        try { URL.revokeObjectURL(v3SingleImageBlobUrls[key]); } catch (e) {}
        delete v3SingleImageBlobUrls[key];
    }

    var file = fileInput.files && fileInput.files[0];
    if (file) {
        var blobUrl = URL.createObjectURL(file);
        v3SingleImageBlobUrls[key] = blobUrl;
        if (previewImg) {
            previewImg.src = blobUrl;
            previewImg.style.display = 'block';
        }
        if (clearBtn) clearBtn.style.display = 'inline-block';
        if (hiddenInput) hiddenInput.value = blobUrl;
    } else {
        if (previewImg) {
            previewImg.src = '';
            previewImg.style.display = 'none';
        }
        if (clearBtn) clearBtn.style.display = 'none';
        if (hiddenInput) hiddenInput.value = '';
    }
    sendLivePreviewUpdate();
}

function clearV3SingleImage(v3Id, key) {
    var fileInput = document.getElementById('file_' + v3Id);
    var previewImg = document.getElementById('preview_' + v3Id);
    var clearBtn = document.getElementById('clear_' + v3Id);
    var hiddenInput = document.getElementById(v3Id);
    if (fileInput) fileInput.value = '';
    if (v3SingleImageBlobUrls[key]) {
        try { URL.revokeObjectURL(v3SingleImageBlobUrls[key]); } catch (e) {}
        delete v3SingleImageBlobUrls[key];
    }
    if (previewImg) {
        previewImg.src = '';
        previewImg.style.display = 'none';
    }
    if (clearBtn) clearBtn.style.display = 'none';
    if (hiddenInput) hiddenInput.value = '';
    sendLivePreviewUpdate();
}

var v3LastSignature = '';
var v3PreviewTimer = null;
function v3LivePreview(photoUrls, musicUrl) {
    var urlParams = new URLSearchParams(window.location.search);
    var tplId = urlParams.get('id') || '69';
    if (tplId !== '69') return; // Strict lock: Only template 69 uses server-rendered live.php

    // "Nhạc gốc" -> không gửi nhạc, để mẫu tự phát đúng bài mặc định của nó.
    var originalPicked = document.querySelector('.music-card--original.selected');
    var uploadPicked = document.getElementById('music_upload') && document.getElementById('music_upload').files && document.getElementById('music_upload').files[0];
    if (originalPicked && !uploadPicked && !(document.getElementById('music_url') || {}).value) musicUrl = '';
    var fields = {};
    document.querySelectorAll('#sec-v3 .v3-input').forEach(function(el) {
        fields[el.name] = el.type === 'checkbox' ? (el.checked ? '1' : '0') : el.value;
    });
    var v3RecEl = document.getElementById('v3_recipient_name');
    var recipientName = (v3RecEl && v3RecEl.value.trim() !== '')
        ? v3RecEl.value.trim()
        : (document.getElementById('recipient_name') ? document.getElementById('recipient_name').value : '').trim();
    var senderName = (document.getElementById('sender_name') ? document.getElementById('sender_name').value : '').trim();
    var message = (document.getElementById('message') ? document.getElementById('message').value : '').trim();
    var password = (document.getElementById('pass_toggle') && document.getElementById('pass_toggle').checked && document.getElementById('password_value')) ? document.getElementById('password_value').value.trim() : '';
    var inlineInfo = document.getElementById('v3-inline-album-info');
    if (inlineInfo) {
        if (photoUrls && photoUrls.length > 0) {
            inlineInfo.textContent = '✅ Đã chọn ' + photoUrls.length + ' ảnh cho Quả cầu kỷ niệm 3D.';
        } else {
            inlineInfo.textContent = '✨ Nếu chưa tải ảnh lên, quả cầu 3D sẽ dùng bộ ảnh mẫu mặc định (Miễn phí).';
        }
    }
    var signature = JSON.stringify([fields, photoUrls, musicUrl || "", recipientName, senderName, message, password]);
    if (signature === v3LastSignature) return;
    clearTimeout(v3PreviewTimer);
    v3PreviewTimer = setTimeout(function() {
        v3LastSignature = signature;
        var form = document.createElement('form');
        form.method = 'POST';
        form.action = 'templates/_v3/live.php';
        form.target = 'v3-live-preview';
        form.style.display = 'none';
        var add = function(name, value) {
            var input = document.createElement('input');
            input.type = 'hidden'; input.name = name; input.value = value;
            form.appendChild(input);
        };
        add('slug', "mon-qua-nho-2010");
        add('photos_json', JSON.stringify(photoUrls));
        add("music", musicUrl || "");
        add('recipient_name', recipientName);
        add('sender_name', senderName);
        add('message', message);
        add('password', password);
        Object.keys(fields).forEach(function(name) { add(name, fields[name]); });
        document.body.appendChild(form);
        form.submit();
        form.remove();
    }, 600);
}
document.addEventListener('input', function(e) {
    if (e.target && e.target.classList && e.target.classList.contains('v3-input')) sendLivePreviewUpdate();
});
document.addEventListener('change', function(e) {
    if (e.target && e.target.classList && e.target.classList.contains('v3-input')) sendLivePreviewUpdate();
});
function sendLivePreviewUpdate() {
    var frame = document.getElementById('gift-live-preview');
    if (!frame || !frame.contentWindow) return;

    var photosEl = document.getElementById('photos');
    var photoUrls = [];
    var cutouts = [];
    var useDefault = document.getElementById('use_default_photos') && document.getElementById('use_default_photos').checked;
    var sourcePhotos = (_preparedMainPhotos && _preparedMainPhotos.length > 0) ? _preparedMainPhotos : (photosEl && photosEl.files ? Array.from(photosEl.files) : []);
    
    if (useDefault) {
        photoUrls = ['womens-day/assets/images/icons/couple.png', 'womens-day/assets/images/characters/bearflower.png'];
        cutouts = [true, true];
    } else if (sourcePhotos.length > 0) {
        var count = Math.min(sourcePhotos.length, 20);
        for (var i = 0; i < count; i++) {
            photoUrls.push(livePreviewObjectUrl(sourcePhotos[i]));
            cutouts.push(!!sourcePhotos[i]._isCutout);
        }
    }

    var flyPhotosEl = document.getElementById('fly_photos');
    var flyPhotoUrls = [];
    if (flyPhotosEl && flyPhotosEl.files && flyPhotosEl.files.length > 0) {
        var fCount = Math.min(flyPhotosEl.files.length, 20);
        for (var j = 0; j < fCount; j++) {
            flyPhotoUrls.push(livePreviewObjectUrl(flyPhotosEl.files[j]));
        }
    }

    var popupInput = document.getElementById('popup_image');
    var popupImageUrl = '';
    if (popupInput && popupInput.files && popupInput.files[0]) {
        popupImageUrl = livePreviewObjectUrl(popupInput.files[0]);
    }

    var recipientName = (document.getElementById('recipient_name') ? document.getElementById('recipient_name').value : '').trim();
    var senderName = (document.getElementById('sender_name') ? document.getElementById('sender_name').value : '').trim();
    var morph1 = (document.getElementById('morph_text_1') ? document.getElementById('morph_text_1').value : '').trim();
    var morph2 = (document.getElementById('morph_text_2') ? document.getElementById('morph_text_2').value : '').trim();
    var message = (document.getElementById('message') ? document.getElementById('message').value : '').trim();
    var popupTitle = (document.getElementById('popup_title') ? document.getElementById('popup_title').value : '').trim();
    var popupMessage = (document.getElementById('popup_message') ? document.getElementById('popup_message').value : '').trim();
    var wishes = (document.getElementById('wishes') ? document.getElementById('wishes').value : '').trim();
    var valChatMessages = Array.from(document.querySelectorAll('[name="val_chat_messages[]"]')).map(function(el){ return el.value.trim(); }).filter(Boolean);
    var valLetterContent = (document.getElementById('val_letter_content')?.value || '').trim();
    var valHeartMode = document.querySelector('[name="val_heart_mode"]:checked')?.value || 'days';
    var valChatTheme = document.querySelector('[name="val_chat_theme"]:checked')?.value || 'love';
    var valSingleFileUrl = function(id) {
        var input = document.getElementById(id);
        return input && input.files && input.files[0] ? livePreviewObjectUrl(input.files[0]) : '';
    };
    var originalCard = document.querySelector('.music-card--original.selected');
    var selectedNonOriginal = document.querySelector('.music-card.selected:not(.music-card--original)');
    var musicUpload = document.getElementById('music_upload');
    var hasCustomMusicUpload = !!(musicUpload && musicUpload.files && musicUpload.files[0]);
    var musicUrl = '';
    var preserveDemoAudio = true;

    if (hasCustomMusicUpload) {
        musicUrl = livePreviewObjectUrl(musicUpload.files[0]);
        preserveDemoAudio = false;
    } else if (selectedNonOriginal && selectedNonOriginal.getAttribute('data-value')) {
        musicUrl = (selectedNonOriginal.getAttribute('data-value') || '').trim();
        preserveDemoAudio = false;
    } else {
        // Người dùng không đổi nhạc (giữ nguyên nhạc gốc của demo video)
        musicUrl = '';
        preserveDemoAudio = true;
    }

    var payload = {
        birthday_day: (document.getElementById('birthday_day')?.value || document.getElementById('v3_calendar_day')?.value || '19').trim(),
        birthday_month: (document.getElementById('birthday_month')?.value || document.getElementById('v3_calendar_month')?.value || '11').trim(),
        photos: photoUrls,
        cutouts: cutouts,
        fly_photos: flyPhotoUrls,
        photo_style: 'auto',
        popup_image: popupImageUrl,
        recipient_name: recipientName,
        sender_name: senderName,
        morph_text_1: morph1,
        morph_text_2: morph2,
        message: message,
        galaxy_color: document.getElementById('galaxy_color')?.value || '#e8589a',
        galaxy_icons: (document.getElementById('galaxy_icons')?.value || '♥ 💖 ❤️ 💕').trim(),
        galaxy_heart_text: (document.getElementById('galaxy_heart_text')?.value || recipientName).trim(),
        galaxy_enable_heart: document.getElementById('galaxy_enable_heart') ? document.getElementById('galaxy_enable_heart').checked : true,
        corazon_title: (document.getElementById('corazon_title')?.value || 'TE AMO ❤️').trim(),
        corazon_tap_text: (document.getElementById('corazon_tap_text')?.value || 'Chạm để bắt đầu').trim(),
        popup_title: popupTitle,
        ny_year: (document.getElementById('ny_year')?.value || '').trim(),
        popup_message: popupMessage,
        wishes: wishes,
        music_url: musicUrl,
        preserve_demo_audio: preserveDemoAudio,
        password: document.getElementById('password_value')?.value || '0000',
        val_chat_messages: valChatMessages,
        val_chat_theme: valChatTheme,
        val_chat_avatar: valSingleFileUrl('val_chat_avatar'),
        val_background_image: valSingleFileUrl('val_background_image'),
        val_heart_mode: valHeartMode,
        val_love_start_date: document.getElementById('val_love_start_date')?.value || '',
        val_heart_text: document.getElementById('val_heart_text')?.value || 'Đang Yêu',
        val_boy_photo: valSingleFileUrl('val_boy_photo'),
        val_girl_photo: valSingleFileUrl('val_girl_photo'),
        val_letter_content: valLetterContent,
        val_letter_signature: senderName,
        sweet_pages: (typeof sweetPageTexts === 'function' && document.getElementById('sweet-pages')) ? sweetPageTexts() : null,
        lr_glow: document.getElementById('lr_glow')?.value || 'random',
        lr_direction: document.getElementById('lr_direction')?.value || 'down',
        envelope_top: (document.getElementById('envelope_top')?.value || '').trim(),
        envelope_headline: (document.getElementById('envelope_headline')?.value || '').trim(),
        envelope_bottom: (document.getElementById('envelope_bottom')?.value || '').trim(),
        letter_photo: (function() {
            var input = document.getElementById('pb_letter_photo');
            if (input && input.files && input.files[0]) return livePreviewObjectUrl(input.files[0]);
            var existing = document.getElementById('existing_pb_letter_photo');
            return existing ? existing.value : '';
        })()
    };

    var urlParams = new URLSearchParams(window.location.search);
    var tplId = urlParams.get('id') || '69';

    // 1. Broadcast updates via postMessage to iframe (for interactive demos)
    try {
        frame.contentWindow.postMessage({
            type: 'DG_LIVE_PREVIEW_UPDATE',
            template_id: tplId,
            payload: payload
        }, '*');
        frame.contentWindow.postMessage({
            type: 'LIVE_PREVIEW_UPDATE',
            template_id: tplId,
            data: payload,
            payload: payload
        }, '*');
    } catch(err) {
        console.warn('Live preview postMessage error:', err);
    }

    // 2. Only template 69 posts to templates/_v3/live.php
    if (tplId === '69') {
        v3LivePreview(photoUrls, musicUrl);
    }
}

// Khi iframe báo đã sẵn sàng, gửi lại dữ liệu để đồng bộ ngay
window.addEventListener('message', function(e) {
    var previewFrame = document.getElementById('gift-live-preview');
    if (!previewFrame || e.source !== previewFrame.contentWindow) return;
    if (e.data && e.data.type === 'DG_PREVIEW_READY') sendLivePreviewUpdate();
});

// Lắng nghe iframe load để cập nhật ngay
(function() {
    var pFrame = document.getElementById('gift-live-preview');
    if (pFrame) {
        pFrame.addEventListener('load', function() {
            [200, 700, 1500, 3000].forEach(function(delay) {
                setTimeout(sendLivePreviewUpdate, delay);
            });
        });
    }
})();

function refreshGiftPreview() {
    var frame = document.getElementById('gift-live-preview');
    if (!frame) return;
    var urlParams = new URLSearchParams(window.location.search);
    var tplId = urlParams.get('id') || '69';

    // Đẩy đồng bộ ngay lập tức tới khung đang hiển thị
    if (typeof sendLivePreviewUpdate === 'function') {
        sendLivePreviewUpdate();
    }

    // Đăng ký đồng bộ tự động khi iframe tải lại xong
    var syncTries = [50, 250, 600, 1200, 2200];
    var onFrameReload = function() {
        syncTries.forEach(function(d) {
            setTimeout(function() {
                if (typeof sendLivePreviewUpdate === 'function') sendLivePreviewUpdate();
            }, d);
        });
    };
    frame.addEventListener('load', onFrameReload, { once: true });

    if (tplId === '69') {
        var baseUrl = frame.src.split(/[?&]_preview_refresh=/)[0] || 'templates/_v3/live.php?slug=mon-qua-nho-2010';
        var separator = baseUrl.indexOf('?') === -1 ? '?' : '&';
        frame.src = baseUrl + separator + '_preview_refresh=' + Date.now();
    } else {
        frame.src = 'demo.php?id=' + tplId + '&_preview_refresh=' + Date.now();
    }
}

function setPreviewMode(mode, button) {
    var shell = document.getElementById('gift-live-preview-shell');
    if (!shell) return;
    shell.classList.toggle('phone', mode === 'phone');
    shell.classList.toggle('tablet', mode === 'tablet');
    document.querySelectorAll('[data-preview-mode]').forEach(function (item) {
        item.classList.toggle('active', item === button);
    });
    if (typeof scheduleLivePreview === 'function') {
        setTimeout(function () { scheduleLivePreview(40); }, 260);
    }
}

var _paymentPollTimer = null;
var _pendingShareCode = null;
var _loadingStepInterval = null;
var _giftSubmitting = false;

function startLoadingStepper() {
    var bar = document.getElementById('loading-progress-bar');
    var text = document.getElementById('loading-step-text');
    var steps = [
        { pct: '30%', msg: '✨ Đang xử lý hình ảnh & hiệu ứng 3D...' },
        { pct: '60%', msg: '🎵 Đang kết nối giai điệu âm nhạc...' },
        { pct: '85%', msg: '💌 Đang đóng gói lá thư tình cảm...' },
        { pct: '95%', msg: '🚀 Đang xuất bản món quà của bạn...' }
    ];
    var cur = 0;
    if (bar) bar.style.width = '15%';
    if (text) text.textContent = steps[0].msg;
    
    clearInterval(_loadingStepInterval);
    _loadingStepInterval = setInterval(function() {
        cur++;
        if (cur < steps.length) {
            if (bar) bar.style.width = steps[cur].pct;
            if (text) text.textContent = steps[cur].msg;
        }
    }, 450);
}

function stopLoadingStepper() {
    clearInterval(_loadingStepInterval);
}

function showSuccessCountdownModal(shareCode, viewUrl, redirectUrl) {
    document.getElementById('loading-screen').classList.remove('open');
    stopLoadingStepper();
    
    var modal = document.getElementById('modal-success-countdown');
    var codeEl = document.getElementById('success-share-code');
    var btnView = document.getElementById('btn-view-gift-now');
    var countEl = document.getElementById('success-countdown-seconds');
    var bar = document.getElementById('countdown-progress-bar');
    
    var targetUrl = viewUrl || redirectUrl || 'my-gifts.php';
    if (codeEl) codeEl.textContent = 'DG ' + shareCode;
    if (btnView) btnView.href = targetUrl;
    
    if (modal) modal.style.display = 'flex';
    
    var secondsLeft = 3;
    if (countEl) countEl.textContent = secondsLeft;
    if (bar) bar.style.width = '100%';
    
    var countdownTimer = setInterval(function() {
        secondsLeft--;
        if (countEl) countEl.textContent = secondsLeft;
        if (bar) bar.style.width = ((secondsLeft / 3) * 100) + '%';
        
        if (secondsLeft <= 0) {
            clearInterval(countdownTimer);
            window.location.href = targetUrl;
        }
    }, 1000);
}

function proceedToPayment() {
    if (_giftSubmitting) return;
    if (_mediaPreparing > 0) {
        showToast('Tệp đang được xử lý. Vui lòng đợi vài giây rồi tạo quà.', 'error');
        return;
    }
    _giftSubmitting = true;
    closeModal('modal-incomplete');

    // Show loading with animated progressive stepper
    document.getElementById('loading-screen').classList.add('open');
    startLoadingStepper();

    // Làm mới mã xác nhận ngay trước khi tải tệp để tab mở lâu vẫn tạo được quà.
    var form = document.getElementById('giftForm');
    refreshBuilderCsrfToken(form)
    .then(function() {
        return submitGiftBuilderForm(form, true);
    })
    .then(res => {
        // Handle session expired
        if (res.redirect && !res.success) {
            _giftSubmitting = false;
            document.getElementById('loading-screen').classList.remove('open');
            stopLoadingStepper();
            showToast(DG_IS_GUEST ? 'Bạn cần đăng nhập để tạo quà, đang chuyển đến trang đăng nhập...' : 'Phiên đăng nhập hết hạn, đang chuyển đến trang đăng nhập...', 'error');
            setTimeout(function() { window.location.href = res.redirect; }, 1500);
            return;
        }
        if (res.error) {
            _giftSubmitting = false;
            document.getElementById('loading-screen').classList.remove('open');
            stopLoadingStepper();
            showToast('Lỗi: ' + res.error, 'error');
            return;
        }

        // Kích hoạt thông báo nền bằng một request độc lập để không giữ màn hình chờ.
        if (res.gift_id) {
            fetch('api_process_notification_queue.php', {
                method: 'POST',
                credentials: 'include',
                keepalive: true,
                headers: {'Content-Type': 'application/json', 'X-CSRF-Token': document.querySelector('#giftForm input[name="csrf_token"]').value},
                body: JSON.stringify({gift_id: res.gift_id})
            }).catch(function () {});
        }
        
        // Free gift success -> Show Countdown Modal!
        if (res.is_free) {
            showSuccessCountdownModal(res.share_code, res.view_url, res.redirect);
            return;
        }
        
        // Paid gift -> Show QR Modal
        document.getElementById('loading-screen').classList.remove('open');
        stopLoadingStepper();
        _pendingShareCode = res.share_code;
        showQRModal(res.share_code, res.amount, res.transfer_content, res.qr_url, res.bank || null);
    })
    .catch(err => {
        _giftSubmitting = false;
        document.getElementById('loading-screen').classList.remove('open');
        stopLoadingStepper();
        if (err && err.redirect) {
            showToast(err.message || 'Phiên đăng nhập đã hết hạn.', 'error');
            setTimeout(function() { window.location.href = err.redirect; }, 1200);
            return;
        }
        // Never submit a second time here: the first request may already have created a gift.
        showToast(err && err.message ? err.message : 'Không nhận được phản hồi. Hãy kiểm tra “Quà của tôi” trước khi thử lại.', 'error');
    });
}

var DG_IS_GUEST = false;
try {
    var storedUser = localStorage.getItem('deargift_user') || localStorage.getItem('deargift_customer');
    if (storedUser) {
        DG_IS_GUEST = false;
    }
} catch(e) {}

function submitGiftBuilderForm(form, canRetryCsrf) {
    var fd = new FormData(form);
    // iOS/Safari có thể không cho gán ngược DataTransfer vào input.files.
    // Thay trực tiếp các ảnh đã nén trong FormData để hosting luôn nhận bản nhẹ.
    if (_preparedMainPhotos !== null) {
        fd.delete('photos[]');
        _preparedMainPhotos.forEach(function(file) { fd.append('photos[]', file, file.name); });
    }
    if (_preparedFlyPhotos !== null) {
        fd.delete('fly_photos[]');
        _preparedFlyPhotos.forEach(function(file) { fd.append('fly_photos[]', file, file.name); });
    }
    fd.set('ajax_submit', '1');
    return fetch(form.action, {
        method: 'POST',
        body: fd,
        credentials: 'include',
        headers: { 'Accept': 'application/json' }
    }).then(function(r) {
        return r.text().then(function(text) {
            var payload = null;
            try { payload = JSON.parse(text); } catch (parseError) {}
            if (payload) {
                // CSRF is checked before any gift/media mutation, so this is
                // the only response that is safe to submit automatically once.
                if (canRetryCsrf && payload.code === 'csrf_expired' && payload.csrf_token) {
                    var tokenField = form.querySelector('input[name="csrf_token"]');
                    if (tokenField) tokenField.value = payload.csrf_token;
                    return submitGiftBuilderForm(form, false);
                }
                return payload;
            }

            console.error('[DearGift Builder] Phản hồi không phải JSON', {
                status: r.status,
                requestId: r.headers.get('X-DearGift-Request-ID'),
                contentType: r.headers.get('Content-Type'),
                responseLength: text.length
            });

            if (r.status === 413) {
                throw new Error('Tổng dung lượng ảnh/nhạc vượt giới hạn cho phép. Hãy giảm dung lượng hoặc số lượng tệp.');
            }
            if (r.status === 403) {
                throw new Error('Phiên xác nhận chưa hợp lệ. Vui lòng bấm tạo quà lại.');
            }
            if (r.status >= 500) {
                var requestId = r.headers.get('X-DearGift-Request-ID');
                throw new Error('Máy chủ gặp lỗi khi tạo quà.' + (requestId ? ' Mã kiểm tra: ' + requestId : '') + ' Vui lòng thử lại.');
            }
            throw new Error('Hệ thống chưa trả về dữ liệu hợp lệ. Hãy giảm dung lượng tệp rồi thử lại.');
        });
    });
}

function refreshBuilderCsrfToken(form) {
    return fetch('api_csrf_token.php', {
        method: 'GET',
        credentials: 'include',
        cache: 'no-store',
        headers: { 'Accept': 'application/json' }
    }).then(function(response) {
        return response.json().catch(function() {
            throw new Error('Không thể làm mới phiên xác nhận. Vui lòng thử lại.');
        }).then(function(payload) {
            if (!response.ok || !payload.success || !payload.csrf_token) {
                var error = new Error(payload.error || 'Phiên xác nhận không hợp lệ.');
                if (payload.redirect) error.redirect = payload.redirect;
                throw error;
            }
            var field = form.querySelector('input[name="csrf_token"]');
            if (!field) {
                field = document.createElement('input');
                field.type = 'hidden';
                field.name = 'csrf_token';
                form.appendChild(field);
            }
            field.value = payload.csrf_token;
            return payload.csrf_token;
        });
    });
}

function showQRModal(shareCode, amount, transferContent, qrUrl, bank) {
    document.getElementById('qr-payment-img').src = qrUrl;
    document.getElementById('qr-amount-display').textContent = Number(amount).toLocaleString('vi-VN') + 'đ';
    document.getElementById('qr-transfer-content').textContent = transferContent;
    if (bank) {
        var bankNameEl = document.getElementById('qr-bank-name');
        var bankOwnerEl = document.getElementById('qr-bank-owner');
        var bankAccountEl = document.getElementById('qr-bank-account');
        if (bankNameEl) bankNameEl.textContent = bank.name || '';
        if (bankOwnerEl) bankOwnerEl.textContent = bank.account_name || '';
        if (bankAccountEl) bankAccountEl.textContent = bank.account || '';
    }
    document.getElementById('qr-status-msg').style.background = '#eff6ff';
    document.getElementById('qr-status-msg').style.color = '#1e40af';
    document.getElementById('qr-status-msg').innerHTML = '⏳ Đang chờ xác nhận. Hệ thống tự động duyệt sau 1–2 phút.';
    
    // Show modal
    var modal = document.getElementById('modal-qr-payment');
    modal.style.display = 'flex';
    modal.classList.add('open');
    document.body.classList.add('payment-modal-open');

    // Start polling
    startPaymentPolling(shareCode);
}

function startPaymentPolling(shareCode) {
    stopPaymentPolling();
    _paymentPollTimer = setInterval(function() {
        fetch('ajax_check_payment_status.php?code=' + shareCode, { credentials: 'include' })
        .then(r => r.json())
        .then(res => {
            if (res.status === 'active') {
                stopPaymentPolling();
                document.getElementById('qr-status-msg').style.background = '#dcfce7';
                document.getElementById('qr-status-msg').style.color = '#166534';
                document.getElementById('qr-status-msg').innerHTML = '✅ Thanh toán thành công! Đang chuyển đến trang quản lý...';
                // Show beautiful success overlay
                var overlay = document.createElement('div');
                overlay.id = 'payment-success-overlay';
                overlay.style.cssText = 'position:fixed;top:0;right:0;bottom:0;left:0;inset:0;background:rgba(0,0,0,0.55);z-index:99999;display:flex;align-items:center;justify-content:center;animation:fadeInBg 0.3s ease;';
                overlay.innerHTML = `
                    <div style="background:#fff;border-radius:28px;padding:40px 36px;text-align:center;max-width:320px;width:90%;box-shadow:0 24px 60px rgba(0,0,0,0.2);animation:popIn 0.4s cubic-bezier(.175,.885,.32,1.275);">
                        <div style="font-size:64px;margin-bottom:12px;animation:bounceIcon 0.6s ease 0.2s both;">✅</div>
                        <div style="font-size:22px;font-weight:800;color:#16a34a;margin-bottom:8px;">Thanh toán thành công!</div>
                        <div style="font-size:14px;color:#7a7090;line-height:1.6;margin-bottom:20px;">Quà tặng của bạn đã được kích hoạt.<br>Đang chuyển đến trang quản lý...</div>
                        <div style="background:#dcfce7;border-radius:50px;height:6px;overflow:hidden;">
                            <div style="background:#16a34a;height:100%;width:0%;border-radius:50px;transition:width 2.2s linear;" id="redirect-progress"></div>
                        </div>
                    </div>
                `;
                document.body.appendChild(overlay);
                // Add keyframe styles
                var style = document.createElement('style');
                style.textContent = '@keyframes fadeInBg{from{opacity:0}to{opacity:1}}@keyframes popIn{from{opacity:0;transform:scale(0.7)}to{opacity:1;transform:scale(1)}}@keyframes bounceIcon{0%,100%{transform:scale(1)}40%{transform:scale(1.3)}70%{transform:scale(0.9)}}';
                document.head.appendChild(style);
                // Animate progress bar
                setTimeout(() => { document.getElementById('redirect-progress').style.width = '100%'; }, 50);
                setTimeout(() => { window.location.href = 'my-gifts.php'; }, 2500);
            }
        })
        .catch(() => {});
    }, 3000);
}

function stopPaymentPolling() {
    if (_paymentPollTimer) { clearInterval(_paymentPollTimer); _paymentPollTimer = null; }
}

function confirmPaymentNow() {
    stopPaymentPolling();
    var code = _pendingShareCode || 'DG';
    var btn = document.getElementById('btn-confirm-payment-now');
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '⏳ Đang kích hoạt quà tặng...';
    }
    
    fetch('/api/gifts/confirm_payment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ share_code: code })
    })
    .then(r => r.json())
    .then(res => {
        closeModal('modal-qr-payment');
        var viewUrl = (res && res.view_url) ? res.view_url : ('gift.php?uid=' + code);
        showSuccessModalFinal(code, viewUrl);
    })
    .catch(err => {
        closeModal('modal-qr-payment');
        showSuccessModalFinal(code, 'gift.php?uid=' + code);
    });
}

function downloadPaymentQR() {
    var img = document.getElementById('qr-payment-img');
    if (!img || !img.src) return;
    var a = document.createElement('a');
    a.href = img.src;
    a.target = '_blank';
    a.download = 'vietqr-payment.png';
    a.click();
}

function showSuccessModalFinal(shareCode, viewUrl) {
    var fullUrl = window.location.origin + '/' + viewUrl.replace(/^\//, '');
    var overlay = document.createElement('div');
    overlay.id = 'gift-created-modal';
    overlay.style.cssText = 'position:fixed;top:0;right:0;bottom:0;left:0;inset:0;background:rgba(15,10,26,0.85);z-index:999999;display:flex;align-items:center;justify-content:center;padding:16px;animation:fadeInBg 0.3s ease;';
    overlay.innerHTML = `
        <div style="background:#fff;border-radius:28px;padding:32px 28px;text-align:center;max-width:440px;width:100%;box-shadow:0 24px 60px rgba(0,0,0,0.3);position:relative;border:2px solid #fce7f3;">
            <div style="font-size:56px;margin-bottom:8px;">🎉</div>
            <h2 style="font-size:22px;font-weight:800;color:#16a34a;margin-bottom:6px;">Quà Tặng Đã Kích Hoạt!</h2>
            <p style="font-size:13px;color:#7a7090;line-height:1.5;margin-bottom:18px;">Món quà của bạn đã sẵn sàng. Hãy gửi liên kết này hoặc mã QR cho người thương nhé!</p>
            
            <div style="background:#fff5f8;border:1.5px dashed #f472b6;border-radius:16px;padding:14px;margin-bottom:18px;text-align:left;">
                <label style="font-size:11px;font-weight:700;color:#e8589a;display:block;margin-bottom:6px;text-transform:uppercase;">Liên kết quà tặng độc quyền:</label>
                <div style="display:flex;gap:8px;align-items:center;">
                    <input type="text" readonly value="${fullUrl}" id="giftFinalUrlInput" style="flex:1;padding:10px 12px;border:1.5px solid #eadff5;border-radius:10px;font-size:13px;color:#3d3551;font-weight:600;background:#fff;outline:none;">
                    <button type="button" onclick="copyGiftLink()" id="btnCopyGift" style="background:linear-gradient(135deg,#e8589a,#c44dff);color:#fff;border:none;border-radius:10px;padding:10px 16px;font-weight:700;font-size:13px;cursor:pointer;white-space:nowrap;">Sao chép</button>
                </div>
            </div>

            <div style="display:flex;justify-content:center;margin-bottom:20px;">
                <div style="background:#fff;padding:10px;border-radius:16px;border:1px solid #eadff5;box-shadow:0 4px 14px rgba(0,0,0,0.06);display:inline-block;">
                    <img src="https://api.qrserver.com/v1/create-qr-code/?size=160x160&data=${encodeURIComponent(fullUrl)}" alt="Mã QR quà tặng" style="width:140px;height:140px;display:block;border-radius:8px;">
                    <div style="font-size:11px;color:#a79fb8;font-weight:600;margin-top:6px;">Quét trên điện thoại để mở quà</div>
                </div>
            </div>

            <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px;">
                <a href="${fullUrl}" target="_blank" style="display:flex;align-items:center;justify-content:center;gap:6px;background:linear-gradient(135deg,#e8589a,#e8589a);color:#fff;text-decoration:none;padding:12px;border-radius:50px;font-weight:800;font-size:14px;box-shadow:0 4px 14px rgba(232,88,154,0.35);">
                    👁️ Mở xem quà
                </a>
                <a href="https://api.qrserver.com/v1/create-qr-code/?size=500x500&data=${encodeURIComponent(fullUrl)}" target="_blank" download="ma-qr-tang-qua.png" style="display:flex;align-items:center;justify-content:center;gap:6px;background:#f0fdf4;color:#16a34a;border:1.5px solid #bbf7d0;text-decoration:none;padding:12px;border-radius:50px;font-weight:800;font-size:14px;">
                    📱 Tải mã QR
                </a>
            </div>

            <a href="my-gifts.php" style="display:block;font-size:13px;color:#7a7090;text-decoration:underline;margin-top:10px;font-weight:600;">
                Quản lý tất cả quà tặng đã tạo →
            </a>
        </div>
    `;
    document.body.appendChild(overlay);
}

function copyGiftLink() {
    var input = document.getElementById('giftFinalUrlInput');
    if (!input) return;
    input.select();
    navigator.clipboard.writeText(input.value).then(function() {
        var btn = document.getElementById('btnCopyGift');
        if (btn) {
            btn.innerHTML = '✓ Đã chép!';
            btn.style.background = '#16a34a';
            setTimeout(() => { btn.innerHTML = 'Sao chép'; btn.style.background = 'linear-gradient(135deg,#e8589a,#c44dff)'; }, 2000);
        }
    });
}

function copyText(text) {
    navigator.clipboard.writeText(text).then(function() {
        // Show brief toast
        var toast = document.createElement('div');
        toast.textContent = '✓ Đã sao chép!';
        toast.style.cssText = 'position:fixed;bottom:80px;left:50%;transform:translateX(-50%);background:#3d3551;color:#fff;padding:8px 18px;border-radius:20px;font-size:13px;z-index:99999;';
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 1800);
    });
}

function openModal(id) {
    var el = document.getElementById(id);
    if (!el) return;
    if (id === 'modal-qr-payment') { el.style.display = 'flex'; document.body.classList.add('payment-modal-open'); }
    el.classList.add('open');
}
function closeModal(id) {
    var el = document.getElementById(id);
    if (!el) return;
    el.classList.remove('open');
    if (id === 'modal-qr-payment') { el.style.display = 'none'; document.body.classList.remove('payment-modal-open'); }
}

// Init
if (document.getElementById('pass_toggle')) togglePasswordSection();
if (document.getElementById('enable_qr')) toggleQRSection();
setTimeout(initAllQrPreviews, 100);
updateTotal();
(function() {
    var firstMusic = document.querySelector('.music-card--original') || document.querySelector('.music-card');
    var sourceType = document.getElementById('music_source_type');
    var uploadInput = document.getElementById('music_upload');
    var hasUpload = !!(uploadInput && uploadInput.files && uploadInput.files.length);
    if (firstMusic && sourceType && sourceType.value === 'preset' && !hasUpload && !document.getElementById('music_url').value) {
        selectMusicCard(firstMusic);
    }
})();
</script>

