<script src="js/demo-preview.js?v=1790353450" defer></script>
<script>
    // Initialize Lucide icons
    lucide.createIcons();

    // Global Toast Notification System
    function showToast(message, type = 'success') {
        let toastContainer = document.getElementById('toast-container');
        if (!toastContainer) {
            toastContainer = document.createElement('div');
            toastContainer.id = 'toast-container';
            toastContainer.style.cssText = 'position: fixed; top: 20px; left: 50%; transform: translateX(-50%); z-index: 9999; display: flex; flex-direction: column; gap: 10px; pointer-events: none;';
            document.body.appendChild(toastContainer);
        }

        const toast = document.createElement('div');
        const bgColor = type === 'error' ? '#fef2f2' : '#f0fdf4';
        const borderColor = type === 'error' ? '#fecaca' : '#bbf7d0';
        const iconColor = type === 'error' ? '#ef4444' : '#22c55e';
        const iconSvg = type === 'error' 
            ? '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="15" y1="9" x2="9" y2="15"></line><line x1="9" y1="9" x2="15" y2="15"></line></svg>'
            : '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path><polyline points="22 4 12 14.01 9 11.01"></polyline></svg>';

        toast.style.cssText = `
            background: ${bgColor}; 
            border: 1px solid ${borderColor}; 
            color: #3d3551; 
            padding: 12px 20px; 
            border-radius: 50px; 
            font-size: 14px; 
            font-weight: 600; 
            display: flex; 
            align-items: center; 
            gap: 10px; 
            box-shadow: 0 10px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);
            opacity: 0;
            transform: translateY(-20px);
            transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
        `;
        
        toast.innerHTML = `<span style="color: ${iconColor}; display: flex;">${iconSvg}</span> <span>${message}</span>`;
        toastContainer.appendChild(toast);

        // Animate in
        requestAnimationFrame(() => {
            toast.style.opacity = '1';
            toast.style.transform = 'translateY(0)';
        });

        // Animate out
        setTimeout(() => {
            toast.style.opacity = '0';
            toast.style.transform = 'translateY(-20px)';
            setTimeout(() => toast.remove(), 300);
        }, 3000);
    }

    // ─── Dynamic Template Binding ──────────────────────────────────────────
    function initDynamicTemplate() {
        var params = new URLSearchParams(window.location.search);
        var tplId = params.get('id') || '69';
        var tpl = (window.DG_TEMPLATES && window.DG_TEMPLATES[tplId]) ? window.DG_TEMPLATES[tplId] : {
            id: tplId,
            title: 'Món Quà Ý Nghĩa 🎁',
            price: '50.000đ',
            demo_url: 'demo.php?id=' + tplId
        };

        // 1. Form action & hidden template_id
        var form = document.getElementById('giftForm');
        if (form) form.action = 'gift-builder.php?id=' + tplId;
        var hiddenTpl = document.getElementById('hidden_template_id');
        if (hiddenTpl) hiddenTpl.value = tplId;

        // 2. Preview Title & Iframe src
        var titleEl = document.querySelector('.gb-live-preview-title');
        if (titleEl) {
            titleEl.innerHTML = '👀 Xem trước: ' + tpl.title;
        }
        var previewFrame = document.getElementById('gift-live-preview');
        if (previewFrame) {
            if (tplId === '69') {
                previewFrame.src = 'templates/_v3/live.php?slug=mon-qua-nho-2010';
            } else {
                previewFrame.src = 'demo.php?id=' + tplId;
            }
        }

        // 3. Price Display
        var prTemplate = document.getElementById('pr-template');
        if (prTemplate && tpl.price) {
            prTemplate.textContent = tpl.price;
        }

        // 4. Tab and Section Visibility
        var tabV3 = document.getElementById('tab-sec-v3');
        var tabLetter = document.getElementById('tab-sec-letter');
        var secV3 = document.getElementById('sec-v3');
        var secLetter = document.getElementById('sec-letter');

        if (tplId === '69') {
            // Multi-scene Template 69
            if (tabV3) { tabV3.style.display = ''; tabV3.classList.add('active'); }
            if (tabLetter) { tabLetter.style.display = 'none'; tabLetter.classList.remove('active'); }
            if (secV3) { secV3.style.display = ''; secV3.classList.add('active'); }
            if (secLetter) { secLetter.classList.remove('active'); }
        } else {
            // Non-69 templates: Hide the 7-scene editor, show clean Letter/Wishes editor
            if (tabV3) { tabV3.style.display = 'none'; tabV3.classList.remove('active'); }
            if (tabLetter) { tabLetter.style.display = ''; tabLetter.classList.add('active'); }
            if (secV3) { secV3.style.display = 'none'; secV3.classList.remove('active'); }
            if (secLetter) { secLetter.style.display = ''; secLetter.classList.add('active'); }
            
            // Update photo tab label
            var photoLabel = document.querySelector('[data-section="sec-photos"] .tab-label');
            if (photoLabel) photoLabel.textContent = 'Ảnh kỷ niệm';
        }

        // 5. Kiểm tra mẫu có hỗ trợ/thích hợp dùng ảnh hay không
        var NO_PHOTO_TEMPLATES = ['8', '9', '27', '28', '37', '44', '45', '49', '54', '62', '63', '64', '67'];
        var photoTab = document.querySelector('[data-section="sec-photos"]');
        var photoSec = document.getElementById('sec-photos');
        var allowsPhoto = NO_PHOTO_TEMPLATES.indexOf(String(tplId)) === -1;

        if (!allowsPhoto) {
            if (photoTab) photoTab.style.display = 'none';
            if (photoSec) photoSec.style.display = 'none';
            if (photoTab && photoTab.classList.contains('active')) {
                photoTab.classList.remove('active');
                if (tplId === '69' && tabV3) {
                    tabV3.classList.add('active');
                    if (secV3) secV3.style.display = '';
                } else if (tabLetter) {
                    tabLetter.classList.add('active');
                    if (secLetter) secLetter.style.display = '';
                }
            }
        } else {
            if (photoTab) photoTab.style.display = '';
        }

        // Always recalculate pricing when template is bound
        if (typeof updateTotal === 'function') {
            updateTotal();
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initDynamicTemplate);
    } else {
        initDynamicTemplate();
    }
    
</script>


<script>
